    lines = x.strip().split('\n')
    n = int(lines[0])
    if n > 10:  # only compute for small inputs
        return
    pairs = []
    for line in lines[1:]:
        a,b = map(int, line.split())
        pairs.append((a,b))
    ids = set()
    for a,b in pairs:
        if a>0: ids.add(a)
        if b>0: ids.add(b)
    from itertools import permutations
    for perm in permutations(ids):
        ok = True
        # check neighbor records
        for a,b in pairs:
            if a==0 and b==0:
                continue
            if a==0:
                # b must be first in perm
                if perm[0]!=b:
                    ok=False
                    break
            elif b==0:
                # a must be last in perm
                if perm[-1]!=a:
                    ok=False
                    break
            else:
                # find index of a in perm
                try:
                    idx = perm.index(a)
                except ValueError:
                    ok=False
                    break
                if idx==n-1 or perm[idx+1]!=b:
                    ok=False
                    break
        if ok:
            # found a valid permutation; compare with output
            out = tuple(map(int, run(x).strip().split()))
            assert out == perm, f'Output does not match valid queue permutation'
            return
    # if no valid permutation found, something wrong with input (shouldn't happen)
    raise AssertionError('No valid permutation found for input (should be impossible)')


def test_order_respects_pairs(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    prev = {}
    nxt = {}
    for line in lines[1:]:
        a,b = map(int, line.split())
        if a>0:
            prev[b] = a  # a is in front of b
        if b>0:
            nxt[a] = b   # b is behind a
    out = list(map(int, run(x).strip().split()))
    for i in range(1, n):
        if out[i] in prev:
            assert prev[out[i]] == out[i-1], f'Previous neighbor mismatch at position {i}'
    for i in range(n-1):
        if out[i] in nxt:
            assert nxt[out[i]] == out[i+1], f'Next neighbor mismatch at position {i}'

