def test_output_format(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    if len(lines) == 0:
        assert False, 'Empty output'
    first = lines[0].strip()
    assert first in ('Yes', 'No'), f'First line must be Yes or No, got {first}'
    if first == 'Yes':
        assert len(lines) >= 3, f'Yes requires 3 lines, got {len(lines)}'
        try:
            vals1 = list(map(int, lines[1].split()))
            vals2 = list(map(int, lines[2].split()))
        except ValueError:
            assert False, 'Rating lines must be integers'
        n, m = map(int, x.strip().split('\n')[0].split())
        assert len(vals1) == n, f'Expected {n} ratings for first set, got {len(vals1)}'
        assert len(vals2) == m, f'Expected {m} ratings for second set, got {len(vals2)}'
    else:
