def test_last_row_operation_dominant(run, x):
    import sys
    data = list(map(str.split, x.strip().split('\n')))
    n, m, k = map(int, data[0])
    ops = []
    for i in range(1, k+1):
        t, idx, col = map(int, data[i])
        ops.append((t, idx-1, col, i-1))
    out = run(x).strip('\n').split('\n')
    # For each row, find the latest row operation
    row_last = [-1] * n
    row_color = [0] * n
    for (t, idx, col, tim) in ops:
        if t == 1:
            row_last[idx] = tim
            row_color[idx] = col
    # For any cell where the latest operation overall is a row op,
    # its color must match that row op's color.
    # We can't recompute overall latest, but we can check that
    # if a row's latest op is later than any column op on that cell,
    # then the cell must be that row color.
    # However we don't know column timestamps without recomputing.
    # Instead, check: if the row's latest op is the very last operation
    # in the whole sequence and it's a row op, then all cells in that row
    # must be that color.
    if not ops:
        return
    last_op = ops[-1]
    if last_op[0] == 1:
        r = last_op[1]
        expected = last_op[2]
        row_vals = list(map(int, out[r].strip().split()))
        for v in row_vals:
            assert v == expected


