def test_output_format(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    # First line Yes/No
    assert len(lines) >= 1
    first = lines[0].strip()
    assert first in ('Yes', 'No')
    if first == 'Yes':
        # Must have 3 lines total
        assert len(lines) == 3
        # Second line: n integers
        vals1 = list(map(int, lines[1].split()))
        n, m = map(int, x.strip().split('\n')[0].split())
        assert len(vals1) == n
        # Third line: m integers
        vals2 = list(map(int, lines[2].split()))
        assert len(vals2) == m
        # All positive integers
        assert all(v > 0 for v in vals1 + vals2)
    else:
        # No: must be exactly one line
        assert len(lines) == 1


def test_consistency_with_inequalities(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    if lines[0].strip() != 'Yes':
        return
    n, m = map(int, x.strip().split('\n')[0].split())
    rows = x.strip().split('\n')[1:1+n]
    vals1 = list(map(int, lines[1].split()))
    vals2 = list(map(int, lines[2].split()))
    for i in range(n):
        for j in range(m):
            c = rows[i][j]
            if c == '<':
                assert vals1[i] < vals2[j]
            elif c == '>':
                assert vals1[i] > vals2[j]
            else:  # '='
                assert vals1[i] == vals2[j]


def test_equality_transitive(run, x):
    # If any row has all '=', then all first‑day dishes in that row must have same value
    # and all second‑day dishes must have that same value as well.
    out = run(x)
    lines = out.strip().split('\n')
    if lines[0].strip() != 'Yes':
        return
    n, m = map(int, x.strip().split('\n')[0].split())
    rows = x.strip().split('\n')[1:1+n]
    vals1 = list(map(int, lines[1].split()))
    vals2 = list(map(int, lines[2].split()))
    # For each row, if all columns are '=', then vals1[i] must equal all vals2[j]
    for i in range(n):
        if all(c == '=' for c in rows[i]):
            for j in range(m):
                assert vals1[i] == vals2[j]
    # For each column, if all rows are '=', then vals2[j] must equal all vals1[i]
    for j in range(m):
        if all(rows[i][j] == '=' for i in range(n)):
            for i in range(n):
                assert vals1[i] == vals2[j]


def test_no_contradiction_small(run, x):
    # For very small n,m (≤4), brute‑force check if assignment exists.
    # If brute‑force says impossible, output must be No.
    # If brute‑force says possible, output must be Yes (and we rely on other tests for values).
    n, m = map(int, x.strip().split('\n')[0].split())
    if n > 4 or m > 4:
        return  # too large for brute force
    rows = x.strip().split('\n')[1:1+n]
    # Try all values from 1..(n+m) (enough)
    from itertools import product
    maxv = n + m
    possible = False
    for vals1 in product(range(1, maxv+1), repeat=n):
        for vals2 in product(range(1, maxv+1), repeat=m):
            ok = True
            for i in range(n):
                for j in range(m):
                    c = rows[i][j]
                    if c == '<':
                        if vals1[i] >= vals2[j]:
                            ok = False
                    elif c == '>':
                        if vals1[i] <= vals2[j]:
                            ok = False
                    else:
                        if vals1[i] != vals2[j]:
                            ok = False
                if not ok:
                    break
            if not ok:
                continue
            possible = True
            break
        if possible:
            break
    out = run(x)
    lines = out.strip().split('\n')
    if possible:
        assert lines[0].strip() == 'Yes'
    else:
        assert lines[0].strip() == 'No'


