def test_contradiction_direct(run, x):
    # Simple direct contradictions: a_ij='<' and a_ij='>' impossible; but also
    # if a_ij='<' and a_ji='>' (when n=m) leads to contradiction.
    # We only check within the given table: if for some i,j we have both
    # a_ij='<' and a_ij='>' (cannot happen), skip.
    # Actually we can check cycles of length 2 via equality merging.
    # Build graph of inequalities ignoring '=' merged nodes.
    n, m = map(int, x.strip().split('\n')[0].split())
    rows = x.strip().split('\n')[1:1+n]
    # treat each dish as node 0..n-1 and n..n+m-1
    parent = list(range(n+m))
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(a,b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[rb] = ra
    for i in range(n):
        for j in range(m):
            if rows[i][j] == '=':
                union(i, n+j)
    edges = []
    for i in range(n):
        for j in range(m):
            if rows[i][j] == '<':
                u = find(i); v = find(n+j)
                edges.append((u, v, '<'))
            elif rows[i][j] == '>':
                u = find(i); v = find(n+j)
                edges.append((v, u, '<'))  # reverse
    # check for a cycle in the inequality graph (ignoring direction weight)
    # Build adjacency for DFS
    nodes = set()
    for u,v,_ in edges:
        nodes.add(u); nodes.add(v)
    nodes = list(nodes)
    idx = {node:i for i,node in enumerate(nodes)}
    k = len(nodes)
    adj = [[] for _ in range(k)]
    for u,v,_ in edges:
        adj[idx[u]].append(idx[v])
    # if there's a cycle, impossible
    visited = [0]*k
    def dfs(u):
        visited[u] = 1
        for v in adj[u]:
            if visited[v] == 1:
                return True
            if visited[v] == 0:
                if dfs(v):
                    return True
        visited[u] = 2
        return False
    has_cycle = False
    for i in range(k):
        if visited[i] == 0:
            if dfs(i):
                has_cycle = True
                break
    out = run(x)
    lines = out.strip().split('\n')
    if has_cycle:
        assert lines[0].strip() == 'No'


def test_values_positive_integers(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    if lines[0].strip() != 'Yes':
        return
    vals1 = list(map(int, lines[1].split()))
    vals2 = list(map(int, lines[2].split()))
    assert all(isinstance(v, int) for v in vals1 + vals2)
    assert all(v >= 1 for v in vals1 + vals2)


def test_maximality_small(run, x):
    # For very small n,m (≤3), check that maximum value is minimal possible.
    n, m = map(int, x.strip().split('\n')[0].split())
    if n > 3 or m > 3:
        return
    rows = x.strip().split('\n')[1:1+n]
    out = run(x)
    lines = out.strip().split('\n')
    if lines[0].strip() != 'Yes':
        return
    vals1 = list(map(int, lines[1].split()))
    vals2 = list(map(int, lines[2].split()))
    max_used = max(vals1 + vals2)
    # brute‑force search for minimal possible maximum
    from itertools import product
    best = n + m + 1
    for vals1_try in product(range(1, n+m+1), repeat=n):
        for vals2_try in product(range(1, n+m+1), repeat=m):
            ok = True
            for i in range(n):
                for j in range(m):
                    c = rows[i][j]
                    if c == '<':
                        if vals1_try[i] >= vals2_try[j]:
                            ok = False
                    elif c == '>':
                        if vals1_try[i] <= vals2_try[j]:
                            ok = False
                    else:
                        if vals1_try[i] != vals2_try[j]:
                            ok = False
                if not ok:
                    break
            if ok:
                best = min(best, max(max(vals1_try), max(vals2_try)))
    assert max_used == best


def test_strict_inequality_chains(run, x):
    # If there is a chain a_i1 < b_j1, b_j1 < a_i2, a_i2 < b_j2, ...
    # then values must strictly increase along chain.
    # We'll just test that for each pair of first‑day dishes i1,i2
    # if there exists j such that a_i1,j='<' and a_i2,j='>' then val[i1] < val[i2].
    out = run(x)
    lines = out.strip().split('\n')
    if lines[0].strip() != 'Yes':
        return
    n, m = map(int, x.strip().split('\n')[0].split())
    rows = x.strip().split('\n')[1:1+n]
    vals1 = list(map(int, lines[1].split()))
    vals2 = list(map(int, lines[2].split()))
    for i1 in range(n):
        for i2 in range(n):
            if i1 == i2:
                continue
            less = False
            greater = False
            for j in range(m):
                if rows[i1][j] == '<' and rows[i2][j] == '>':
                    less = True
                if rows[i1][j] == '>' and rows[i2][j] == '<':
                    greater = True
            if less:
                assert vals1[i1] < vals1[i2]
            if greater:
                assert vals1[i1] > vals1[i2]
    # similarly for second‑day dishes
    for j1 in range(m):
        for j2 in range(m):
            if j1 == j2:
                continue
            less = False
            greater = False
            for i in range(n):
                if rows[i][j1] == '<' and rows[i][j2] == '>':
                    less = True
                if rows[i][j1] == '>' and rows[i][j2] == '<':
                    greater = True
            if less:
                assert vals2[j1] < vals2[j2]
            if greater:
                assert vals2[j1] > vals2[j2]

