    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    vals = list(map(int, lines[1].split()))
    # longest subsequence alternating between two values
    from collections import defaultdict
    pos = defaultdict(list)
    for idx, v in enumerate(vals):
        pos[v].append(idx)
    best = 0
    unique_vals = list(pos.keys())
    for i in range(len(unique_vals)):
        for j in range(i+1, len(unique_vals)):
            a, b = unique_vals[i], unique_vals[j]
            # greedy alternating picking
            seq = []
            ia = ib = 0
            while True:
                # pick next a after last pick
                while ia < len(pos[a]) and (seq and pos[a][ia] <= seq[-1]):
                    ia += 1
                if ia >= len(pos[a]):
                    break
                seq.append(pos[a][ia])
                # pick next b after that
                while ib < len(pos[b]) and (seq and pos[b][ib] <= seq[-1]):
                    ib += 1
                if ib >= len(pos[b]):
                    break
                seq.append(pos[b][ib])
            best = max(best, len(seq))
            # also try starting with b
            seq = []
            ia = ib = 0
            while True:
                while ib < len(pos[b]) and (seq and pos[b][ib] <= seq[-1]):
                    ib += 1
                if ib >= len(pos[b]):
                    break
                seq.append(pos[b][ib])
                while ia < len(pos[a]) and (seq and pos[a][ia] <= seq[-1]):
                    ia += 1
                if ia >= len(pos[a]):
                    break
                seq.append(pos[a][ia])
            best = max(best, len(seq))
    ans = int(run(x).strip())
    assert ans >= best"
    }
