      "source": "def test_small_exact_bruteforce(run, x):
    data = x.strip().split()
    if len(data) < 2:
        return
    n = int(data[0])
    if n > 6:
        return
    vals = list(map(int, data[1:1+n]))
    best = 0
    from itertools import combinations
    for k in range(1, n+1):
        for idx in combinations(range(n), k):
            sub = [vals[i] for i in idx]
            if len(sub) < 2:
                ok = True
            else:
                p = sub[0]
                q = sub[1] - sub[0]
                ok = all(sub[i] == p + ((i%2==0) and q or -q) for i in range(len(sub)))
                # equivalent to a1 = p, a_i = a_{i-1} + (-1)^{i+1} * q
                # check: a2 = p + q, a3 = p+q - q = p, a4 = p + q, ...
                # so sub[i] must equal p + q if i%2==1 else p
                # Wait, careful: formula: a_i = a_{i-1} + (-1)^{i+1} * q
