      "source": "def test_brute_force_small_n(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n > 6:  # brute force over 2^n splits is too big for n>6
        return
    names = lines[1:1+n]
    # compute minimum by trying all assignments
    best = float('inf')
    for mask in range(1 << n):
        cntA = {}
        cntB = {}
        for i in range(n):
            ch = names[i][0]
            if (mask >> i) & 1:
                cntA[ch] = cntA.get(ch, 0) + 1
            else:
                cntB[ch] = cntB.get(ch, 0) + 1
        pairs = 0
        for v in cntA.values():
            pairs += v*(v-1)//2
        for v in cntB.values():
            pairs += v*(v-1)//2
        if pairs < best:
            best = pairs
    ans = int(run(x).strip())
    assert ans == best"
