def test_output_format(run, x):
    out = run(x).strip()
    assert out.isdigit() or (out[0]=='-' and out[1:].isdigit()), 'output must be integer'
    ans = int(out)
    assert 1 <= ans <= 10**18, 'length must be in [1,1e18]'

def test_answer_at_least_one(run, x):
    X, Y = map(int, x.split())
    ans = int(run(x).strip())
    assert ans >= 1, 'sequence of length at least 1 always exists'

def test_answer_not_exceed_possible(run, x):
    X, Y = map(int, x.split())
    ans = int(run(x).strip())
    # maximum possible length if we multiply by 2 each time starting from X
    max_possible = 0
    cur = X
    while cur <= Y:
        max_possible += 1
        if cur > Y // 2:
            break
        cur *= 2
    assert ans <= max_possible, 'answer cannot exceed trivial doubling bound'

def test_brute_force_small_x_y(run, x):
    X, Y = map(int, x.split())
    if Y > 1000:
        return  # skip large cases
    # brute force DP: max length starting from each number
    dp = {}
    for v in range(Y, X-1, -1):
        best = 1
        for m in range(2, Y//v + 1):
            nxt = v * m
            if nxt > Y:
                continue
            best = max(best, 1 + dp[nxt])
        dp[v] = best
    correct = max(dp.values()) if dp else 0
    ans = int(run(x).strip())
    assert ans == correct, 'brute force disagrees'

def test_brute_force_up_to_10(run, x):
    X, Y = map(int, x.split())
    if X > 10 or Y > 100:
        return
    from itertools import product
    best = 0
    # try all sequences of length up to, say, 10
    for length in range(1, 11):
        for seq in product(range(X, Y+1), repeat=length):
            if list(seq) != sorted(set(seq)):
                continue
            ok = True
            for i in range(length-1):
                if seq[i+1] % seq[i] != 0 or seq[i+1] <= seq[i]:
                    ok = False
                    break
            if ok:
                best = max(best, length)
    ans = int(run(x).strip())
    assert ans == best, 'exhaustive search disagrees'

def test_single_element_case(run, x):
    X, Y = map(int, x.split())
    if X == Y:
        ans = int(run(x).strip())
        assert ans == 1, 'single element sequence when X==Y'

def test_power_of_two_chain(run, x):
    X, Y = map(int, x.split())
    # if X is a power of two and Y is large, the doubling chain is optimal
    if X & (X-1) == 0 and X >= 1:  # X power of two
        length = 0
        cur = X
        while cur <= Y:
            length += 1
            if cur > Y // 2:
                break
            cur *= 2
        ans = int(run(x).strip())
        # answer must be at least this length (since doubling chain is valid)
        assert ans >= length, 'doubling chain gives a valid sequence of that length'

def test_monotonic_in_Y(run, x):
    X, Y = map(int, x.split())
    ans = int(run(x).strip())
    # If we increase Y, answer cannot decrease.
    # Check a slightly smaller Y (if possible) by brute for small cases.
    if Y > 1 and Y <= 1000:
        X2, Y2 = X, Y-1
        # compute answer for (X, Y2) via brute force
        dp = {}
        for v in range(Y2, X2-1, -1):
            best = 1
            for m in range(2, Y2//v + 1):
                nxt = v * m
                if nxt > Y2:
                    continue
                best = max(best, 1 + dp[nxt])
            dp[v] = best
        correct2 = max(dp.values()) if dp else 0
        assert ans >= correct2, 'answer for larger Y should not be smaller'

def test_max_length_bound_by_log(run, x):
    X, Y = map(int, x.split())
    ans = int(run(x).strip())
    # Even multiplying by minimal factor 2 each time gives at most floor(log2(Y/X)) + 1
    import math
    if X > 0:
        upper = math.floor(math.log2(Y / X)) + 1 if Y >= X else 0
        # but upper may be huge when X is 1, so cap by sanity
        if upper <= 10**9:
            assert ans <= upper, 'length cannot exceed log2(Y/X)+1'

def test_valid_sequence_exists(run, x):
    X, Y = map(int, x.split())
    ans = int(run(x).strip())
    # we can always construct a sequence of length ans by greedy? Not always.
    # Instead, verify that a sequence of length ans can be constructed for small Y.
    if Y <= 1000:
        # brute force check that a sequence of length ans exists
        # by trying to build one greedily multiplying by 2 each step
        # but more robust: use DP to see max length
        dp = {}
        for v in range(Y, X-1, -1):
            best = 1
            for m in range(2, Y//v + 1):
                nxt = v * m
                if nxt > Y:
                    continue
                best = max(best, 1 + dp[nxt])
            dp[v] = best
        max_possible = max(dp.values()) if dp else 0
        assert ans <= max_possible, 'answer claims longer sequence than possible'

