def test_output_in_range(run, x):
    n, m = map(int, x.strip().split())
    out = int(run(x).strip())
    assert 1 <= out <= n

def test_output_not_m(run, x):
    n, m = map(int, x.strip().split())
    out = int(run(x).strip())
    assert out != m

def test_output_is_end_or_adjacent(run, x):
    n, m = map(int, x.strip().split())
    out = int(run(x).strip())
    assert out == 1 or out == n or out == m-1 or out == m+1

def test_brute_force_small_n(run, x):
    n, m = map(int, x.strip().split())
    if n <= 20:
        best_val = None
        best_prob = -1.0
        for a in range(1, n+1):
            win = sum(1 for c in range(1, n+1) if abs(c-a) < abs(c-m) or (abs(c-a) == abs(c-m) and a == m))
            prob = win / n
            if prob > best_prob or (prob == best_prob and (best_val is None or a < best_val)):
                best_prob = prob
                best_val = a
        out = int(run(x).strip())
        assert out == best_val

def test_even_n_middle_choice(run, x):
    n, m = map(int, x.strip().split())
    if n % 2 == 0 and m == n//2:
        out = int(run(x).strip())
        # Both m-1 and m+1 are equally optimal; min is m-1
        assert out == m-1

def test_m_is_1(run, x):
    n, m = map(int, x.strip().split())
    if m == 1:
        out = int(run(x).strip())
        assert out == 2

def test_m_is_n(run, x):
    n, m = map(int, x.strip().split())
    if m == n:
        out = int(run(x).strip())
        assert out == n-1

def test_large_n_far_from_end(run, x):
    n, m = map(int, x.strip().split())
    if n > 100 and m <= n//2:
        out = int(run(x).strip())
        assert out == m+1
    if n > 100 and m > n//2:
        out = int(run(x).strip())
        assert out == m-1

def test_output_adjacent_to_m(run, x):
    n, m = map(int, x.strip().split())
    out = int(run(x).strip())
    assert abs(out - m) == 1

def test_odd_n_exact_middle(run, x):
    n, m = map(int, x.strip().split())
    if n % 2 == 1 and m == (n+1)//2:
        out = int(run(x).strip())
        assert out == m-1

