def test_correct_answer(run, x):
    # Compute the correct answer according to the specification.
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    s = lines[1]
    t = lines[2]
    expected = 'NO'
    if '*' in s:
        prefix, suffix = s.split('*')
        if t.startswith(prefix) and t.endswith(suffix):
            middle_len = len(t) - len(prefix) - len(suffix)
            if middle_len >= 0:
                # The middle part can be any lowercase letters, always okay.
                expected = 'YES'
    else:
        if s == t:
            expected = 'YES'
    actual = run(x).strip()
    assert actual == expected, f'Expected {expected}, got {actual}'

def test_output_format(run, x):
    out = run(x)
    assert out in ('YES\n', 'NO\n'), f'Output must be YES\n or NO\n, got {repr(out)}'

def test_no_star_eq(run, x):
    lines = x.strip().split('\n')
    s = lines[1]
    t = lines[2]
    if '*' not in s:
        out = run(x).strip()
        if out == 'YES':
            assert s == t, f'YES but s != t: {s} vs {t}'
        else:
            assert s != t, f'NO but s == t: {s}'

def test_yes_star_prefix(run, x):
    lines = x.strip().split('\n')
    s = lines[1]
    t = lines[2]
    if '*' in s:
        prefix, suffix = s.split('*')
        out = run(x).strip()
        if out == 'YES':
            assert t.startswith(prefix), f'YES but t does not start with prefix {prefix}'

def test_yes_star_suffix(run, x):
    lines = x.strip().split('\n')
    s = lines[1]
    t = lines[2]
    if '*' in s:
        prefix, suffix = s.split('*')
        out = run(x).strip()
        if out == 'YES':
            assert t.endswith(suffix), f'YES but t does not end with suffix {suffix}'

def test_yes_star_length(run, x):
    lines = x.strip().split('\n')
    s = lines[1]
    t = lines[2]
    if '*' in s:
        prefix, suffix = s.split('*')
        out = run(x).strip()
        if out == 'YES':
            assert len(prefix) + len(suffix) <= len(t), f'YES but prefix+suffix longer than t'

def test_no_star_mismatch(run, x):
    lines = x.strip().split('\n')
    s = lines[1]
    t = lines[2]
    if '*' not in s:
        out = run(x).strip()
        if out == 'NO':
            assert s != t, f'NO but s == t: {s}'

def test_no_star_condition(run, x):
    lines = x.strip().split('\n')
    s = lines[1]
    t = lines[2]
    if '*' in s:
        prefix, suffix = s.split('*')
        out = run(x).strip()
        if out == 'NO':
            # At least one of the necessary conditions for YES must be false.
            cond1 = t.startswith(prefix)
            cond2 = t.endswith(suffix)
            cond3 = len(prefix) + len(suffix) <= len(t)
            assert not (cond1 and cond2 and cond3), f'NO but all conditions for YES hold'

def test_star_at_edges(run, x):
    lines = x.strip().split('\n')
    s = lines[1]
    t = lines[2]
    if '*' in s:
        prefix, suffix = s.split('*')
        # If '*' at beginning, prefix is empty; at end, suffix empty.
        # The solution should handle empty strings correctly.
        # This test doesn't assert anything about output, just that it runs.
        # But we can check that if answer is YES, the conditions hold (already covered).
        # So just a placeholder that does nothing but could be extended.
        pass

def test_yes_empty_wildcard(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    s = lines[1]
    t = lines[2]
    if '*' in s:
        prefix, suffix = s.split('*')
        out = run(x).strip()
        if out == 'YES' and len(t) == len(s) - 1:
            # wildcard replacement must be empty
            assert t == prefix + suffix, f'YES with empty wildcard but t != prefix+suffix'

