        visited = set([start])
        q = deque([start])
        found = False
        while q:
            c, o = q.popleft()
            # operation on original
            if o > 0:
                new_state = (c + 1, o + 1)  # one more copy, one more original
                if new_state == target:
                    found = True
                    break
                if new_state not in visited and new_state[0] <= x_val and new_state[1] <= y_val:
                    visited.add(new_state)
                    q.append(new_state)
            # operation on copy
            if c > 0:
                new_state = (c + 2, o)
                if new_state == target:
                    found = True
                    break
                if new_state not in visited and new_state[0] <= x_val and new_state[1] <= y_val:
                    visited.add(new_state)
                    q.append(new_state)
        correct = 'Yes' if found else 'No'
    output = run(x).strip().lower()
    assert output == correct.lower(), f'Brute-force says {correct}, got {output}'

def test_known_examples(run, x):
    # Check that the provided examples are answered correctly.
    # We know from the statement the correct answers for three examples.
    examples = {
        '6 3': 'Yes',
        '4 2': 'No',
        '1000 1001': 'Yes'
    }
    input_str = x.strip()
    if input_str in examples:
        expected = examples[input_str]
        output = run(x).strip().lower()
        assert output == expected.lower(), f'Example {input_str} expects {expected}, got {output}'

