def test_positive_integer_bounds(run, x):
    n = int(x.split()[0])
    ans = int(run(x).strip())
    assert 1 <= ans <= n

def test_answer_divides_n(run, x):
    n = int(x.split()[0])
    ans = int(run(x).strip())
    assert n % ans == 0

def test_bruteforce_small_n(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    if n > 10:  # brute force only for small n
        return
    a = [list(map(int, line.split())) for line in lines[1:1 + n]]
    best = n
    for k in range(1, n + 1):
        if n % k != 0:
            continue
        ok = True
        for i in range(n):
            mirror_i = (i // k) * k + (k - 1 - i % k) if (i // k) % 2 == 1 else i
            if a[i] != a[mirror_i]:
                ok = False
                break
        if ok:
            best = min(best, k)
    assert int(run(x).strip()) == best

def test_mirror_symmetry(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    a = [list(map(int, line.split())) for line in lines[1:1 + n]]
    ans = int(run(x).strip())
    # Check that rows are consistent with mirroring of size ans
    for i in range(n):
        block = i // ans
        pos_in_block = i % ans
        if block % 2 == 0:
            expected_row = a[pos_in_block]
        else:
            expected_row = a[ans - 1 - pos_in_block]
        assert a[i] == expected_row

def test_answer_not_greater_than_n(run, x):
    n = int(x.split()[0])
    ans = int(run(x).strip())
    assert ans <= n

def test_bruteforce_very_small(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    if n > 6:
        return
    a = [list(map(int, line.split())) for line in lines[1:1 + n]]
    # Try all possible k from 1 to n
    possible = []
    for k in range(1, n + 1):
        if n % k != 0:
            continue
        ok = True
        for i in range(n):
            block = i // k
            pos = i % k
            if block % 2 == 0:
                if a[i] != a[pos]:
                    ok = False
                    break
            else:
                if a[i] != a[k - 1 - pos]:
                    ok = False
                    break
        if ok:
            possible.append(k)
    assert int(run(x).strip()) == min(possible)

def test_lower_bound_1(run, x):
    ans = int(run(x).strip())
    assert ans >= 1

def test_if_full_symmetric_then_answer_divides_half(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    a = [list(map(int, line.split())) for line in lines[1:1 + n]]
    ans = int(run(x).strip())
    # If the whole matrix is symmetric under the current length,
    # then ans should be at most that length
    # Specifically, if n is even and the two halves are mirror images,
    # then ans should divide n//2
    if n % 2 == 0:
        half = n // 2
        symmetric = True
        for i in range(half):
            if a[i] != a[n - 1 - i]:
                symmetric = False
                break
        if symmetric:
            assert ans <= half

def test_answer_is_consistent_with_doubling(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    a = [list(map(int, line.split())) for line in lines[1:1 + n]]
    ans = int(run(x).strip())
    # The matrix a must be obtainable by mirroring a base of ans rows
    # Check that for each row i, it matches the appropriate row of the base
    base = a[:ans]
    for i in range(n):
        block = i // ans
        pos = i % ans
        if block % 2 == 0:
            expected = base[pos]
        else:
            expected = base[ans - 1 - pos]
        assert a[i] == expected

def test_answer_matches_examples(run, x):
