        c, t = map(int, lines[i].split())
        if t <= T:
            valid = True
            break
    out = run(x).strip()
    if valid:
        # Should not output TLE
        assert out != 'TLE'
    # If not valid, output must be TLE (checked by other tests)


def test_output_cost_from_valid_routes(run, x):
    lines = x.strip().split('\n')
    n, T = map(int, lines[0].split())
    valid_costs = []
    for i in range(1, n+1):
        c, t = map(int, lines[i].split())
        if t <= T:
            valid_costs.append(c)
    out = run(x).strip()
    if valid_costs:
        # Output must be one of the valid costs
        assert out.isdigit()
        assert int(out) in valid_costs
    else:
        assert out == 'TLE'


def test_output_minimum_for_small_n(run, x):
    lines = x.strip().split('\n')
    n, T = map(int, lines[0].split())
    if n > 20:  # Keep computation small
        return
    valid_costs = []
    for i in range(1, n+1):
        c, t = map(int, lines[i].split())
        if t <= T:
            valid_costs.append(c)
    out = run(x).strip()
    if valid_costs:
        assert out.isdigit()
        assert int(out) == min(valid_costs)
    else:
        assert out == 'TLE'


