    out = run(x).strip()
    if out != 'TLE':
        val = int(out)
        assert 1 <= val <= 1000  # By constraints on c_i


def test_output_leq_all_valid_costs(run, x):
    lines = x.strip().split('\n')
    n, T = map(int, lines[0].split())
    valid_costs = []
    for i in range(1, n+1):
        c, t = map(int, lines[i].split())
        if t <= T:
            valid_costs.append(c)
    out = run(x).strip()
    if valid_costs:
        val = int(out)
        for c in valid_costs:
            assert val <= c
    else:
        assert out == 'TLE'


def test_no_extra_output(run, x):
    out = run(x)
    # Ensure output is a single line
    lines = out.strip().split('\n')
    assert len(lines) == 1
    # Ensure no extra spaces at end of line
    assert out == out.rstrip() + '\n'


def test_output_integer_if_exists(run, x):
    lines = x.strip().split('\n')
    n, T = map(int, lines[0].split())
    has_valid = any(int(lines[i].split()[1]) <= T for i in range(1, n+1))
    out = run(x).strip()
    if has_valid:
        assert out.isdigit()
    else:
        assert out == 'TLE'


