tests_src:
def test_output_length(run, x):
    out = run(x).strip()
    assert len(out) == 3, f'Output length must be 3, got {len(out)}'

def output_starts_with_AB(run, x):
    out = run(x).strip()
    assert out.startswith('AB'), f'Output must start with "AB", got {out}'

def third_char_is_letter(run, x):
    out = run(x).strip()
    assert len(out) == 3, 'precondition'
    third = out[2]
    assert 'A' <= third <= 'Z', f'Third character must be uppercase letter, got {third}'

def output_no_whitespace(run, x):
    out = run(x)
    assert out.strip() == out, 'Output must not have leading/trailing whitespace'

def third_char_c_or_d_for_known_range(run, x):
    n = int(x.strip())
    out = run(x).strip()
    if 1 <= n <= 999:
        assert out[2] == 'C', f'For N={n} third char must be C, got {out[2]}'
    elif 1000 <= n <= 1998:
        assert out[2] == 'D', f'For N={n} third char must be D, got {out[2]}'
    else:
        raise ValueError('Unexpected N')
    # also check first two chars are AB
    assert out.startswith('AB')

def match_sample_999(run, x):
    if x.strip() == '999':
        out = run(x).strip()
        assert out == 'ABC', f'Sample input 999 must output ABC, got {out}'

def match_sample_1000(run, x):
    if x.strip() == '1000':
        out = run(x).strip()
        assert out == 'ABD', f'Sample input 1000 must output ABD, got {out}'

def match_sample_1(run, x):
    if x.strip() == '1':
        out = run(x).strip()
        assert out == 'ABC', f'Sample input 1 must output ABC, got {out}'

def third_char_not_outside_c_d(run, x):
    out = run(x).strip()
    third = out[2]
    assert third in ('C', 'D'), f'Third character must be C or D, got {third}'

def direct_computation_for_all_inputs(run, x):
    n = int(x.strip())
    # specification: N from 1 to 1998 inclusive
    # first 999 rounds ABC, rounds 1000‑1998 ABD
    expected = 'ABC' if n <= 999 else 'ABD'
    out = run(x).strip()
    assert out == expected, f'For N={n} expected {expected}, got {out}'

