def test_output_is_three_chars_and_newline(run, x):
    out = run(x)
    # output must be exactly 4 characters: three letters + newline
    assert len(out) == 4, f'output length {len(out)} != 4'
    assert out[3] == '\n', 'missing newline'
    letters = out[:3]
    assert letters.isalpha() and letters.isupper(), f'letters {letters} not uppercase alphabetic'

def test_output_is_either_ABC_or_ABD(run, x):
    out = run(x)
    letters = out.strip()
    assert letters in ('ABC', 'ABD'), f'output {letters} not ABC or ABD'

def test_N_less_1000_gives_ABC(run, x):
    # parse integer from input, ignoring spaces and leading zeros
    s = x.strip()
    # remove leading plus sign if present
    if s.startswith('+'):
        s = s[1:]
    N = int(s)
    if 1 <= N <= 999:
        out = run(x)
        assert out.strip() == 'ABC', f'expected ABC for N={N}, got {out.strip()}'

def test_N_1000_to_1998_gives_ABD(run, x):
    s = x.strip()
    if s.startswith('+'):
        s = s[1:]
    N = int(s)
    if 1000 <= N <= 1998:
        out = run(x)
        assert out.strip() == 'ABD', f'expected ABD for N={N}, got {out.strip()}'

def test_edge_999_is_ABC(run, x):
    s = x.strip()
    if s.startswith('+'):
        s = s[1:]
    if s == '999' or s == '0999':
        out = run(x)
        assert out.strip() == 'ABC', f'edge 999 must give ABC, got {out.strip()}'

def test_edge_1000_is_ABD(run, x):
    s = x.strip()
    if s.startswith('+'):
        s = s[1:]
    if s == '1000' or s == '01000':
        out = run(x)
        assert out.strip() == 'ABD', f'edge 1000 must give ABD, got {out.strip()}'

def test_edge_1_is_ABC(run, x):
    s = x.strip()
    if s.startswith('+'):
        s = s[1:]
    if s == '1' or s == '001':
        out = run(x)
        assert out.strip() == 'ABC', f'edge 1 must give ABC, got {out.strip()}'

def test_edge_1998_is_ABD(run, x):
    s = x.strip()
    if s.startswith('+'):
        s = s[1:]
    if s == '1998':
        out = run(x)
        assert out.strip() == 'ABD', f'edge 1998 must give ABD, got {out.strip()}'

def test_output_matches_spec_by_computation(run, x):
    s = x.strip()
    if s.startswith('+'):
        s = s[1:]
    N = int(s)
    # spec: rounds 1..999 -> ABC, 1000..1998 -> ABD
    expected = 'ABC' if 1 <= N <= 999 else 'ABD' if 1000 <= N <= 1998 else None
    out = run(x)
    got = out.strip()
    assert got == expected, f'for N={N} expected {expected}, got {got}'

def test_no_extra_output(run, x):
    out = run(x)
    # output must be exactly three uppercase letters and newline, no extra spaces
    lines = out.split('\n')
    assert len(lines) == 2, 'more than one line output'
    assert lines[1] == '', 'extra output after newline'
    letters = lines[0]
    assert len(letters) == 3, 'not exactly three letters before newline'
    assert letters.isalpha() and letters.isupper(), f'invalid letters {letters}'

