def test_output_format(run, x):
    out = run(x)
    assert out in ('YES\n', 'NO\n'), f'Output must be YES\\n or NO\\n, got {repr(out)}'

def test_single_angle(run, x):
    lines = x.strip().split('\n')
    if len(lines) != 2:
        return  # not a single angle case, skip
    n = int(lines[0])
    if n != 1:
        return
    a = int(lines[1])
    out = run(x).strip()
    correct = 'YES' if a % 360 == 0 else 'NO'
    assert out == correct, f'Single angle {a} -> {correct}, got {out}'

def test_all_180_n5(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n != 5:
        return
    arr = list(map(int, lines[1:]))
    if arr != [180, 180, 180, 180, 180]:
        return
    out = run(x).strip()
    # correct answer for five 180's: need subset sum = 450 mod 360 = 90 -> impossible because each is 180, subset sum is multiple of 180, 90 not multiple of 180.
    # Actually the known condition: we need to check if we can get total/2 mod 360 = 0? Wait, the known solution: we need a subset summing to total/2 (mod 360). total=900, half=450, 450 mod 360 = 90. Need subset sum ≡ 90 (mod 360). Since each is 180, subset sum ≡ 0 or 180 (mod 360). 90 not possible, so answer must be NO.
    assert out == 'NO', f'Five 180s must be NO, got {out}'

def test_yes_implies_subset(run, x):
    out = run(x).strip()
    if out != 'YES':
        return
    lines = x.strip().split('\n')
    n = int(lines[0])
    arr = list(map(int, lines[1:]))
    total = sum(arr)
    # If YES, there must exist a subset with sum ≡ total/2 (mod 360)
