def test_modulo_if_not_inf(run, x):
    out = run(x).strip()
    if out == 'inf':
        return
    val = int(out)
    MOD = 10**9 + 7
    assert 0 <= val < MOD, 'finite answer must be in [0, MOD-1]'

def test_answer_nonnegative(run, x):
    out = run(x).strip()
    if out == 'inf':
        return
    val = int(out)
    assert val >= 0, 'finite answer must be >= 0'

def test_bruteforce_small_1(run, x):
    t, a, b = map(int, x.strip().split())
    if max(t, a, b) > 5:
        return
    # brute force over polynomials of degree up to, say, 5 and coefficients up to 5
    # because numbers are tiny.
    ans = 0
    for deg in range(6):
        for c0 in range(6):
            for c1 in range(6):
                for c2 in range(6):
                    for c3 in range(6):
                        for c4 in range(6):
                            for c5 in range(6):
                                coeffs = [c0, c1, c2, c3, c4, c5]
                                # compute P(t)
                                p = 0
                                powt = 1
                                for c in coeffs:
                                    p += c * powt
                                    powt *= t
                                if p != a:
                                    continue
                                # compute P(P(t)) = P(p)
                                q = 0
                                powp = 1
                                for c in coeffs:
                                    q += c * powp
                                    powp *= p
                                if q == b:
                                    ans += 1
    out = run(x).strip()
    if ans == float('inf'):
        assert out == 'inf'
    else:
        if out == 'inf':
            assert False, 'should not be inf for these small values'
        else:
            assert int(out) == ans

def test_bruteforce_small_2(run, x):
    # another brute force with slightly larger limit but still safe
    t, a, b = map(int, x.strip().split())
    if max(t, a, b) > 3:
        return
    # brute over coefficients up to 3, degree up to 3
    ans = 0
    for c0 in range(4):
        for c1 in range(4):
            for c2 in range(4):
                for c3 in range(4):
                    coeffs = [c0, c1, c2, c3]
                    p = 0
                    powt = 1
                    for c in coeffs:
                        p += c * powt
                        powt *= t
                    if p != a:
                        continue
                    q = 0
                    powp = 1
                    for c in coeffs:
                        q += c * powp
                        powp *= p
                    if q == b:
                        ans += 1
    out = run(x).strip()
    if ans == float('inf'):
        assert out == 'inf'
    else:
        if out == 'inf':
            assert False, 'should not be inf for these small values'
        else:
            assert int(out) == ans

