    t, a, b = map(int, x.strip().split())
    if (t, a, b) != (2, 2, 2):
        return
    # from the example, answer is 2
    out = run(x).strip()
    assert out == '2'

def test_bruteforce_example_2(run, x):
    t, a, b = map(int, x.strip().split())
    if (t, a, b) != (2, 3, 3):
        return
    # from the example, answer is 1
    out = run(x).strip()
    assert out == '1'

def test_bruteforce_tiny(run, x):
    t, a, b = map(int, x.strip().split())
    if max(t, a, b) > 2:
        return
    # brute over coefficients 0..2, degree up to 2
    ans = 0
    for c0 in range(3):
        for c1 in range(3):
            for c2 in range(3):
                coeffs = [c0, c1, c2]
                p = 0
                powt = 1
                for c in coeffs:
                    p += c * powt
                    powt *= t
                if p != a:
                    continue
                q = 0
                powp = 1
                for c in coeffs:
                    q += c * powp
                    powp *= p
                if q == b:
                    ans += 1
    out = run(x).strip()
    if ans == float('inf'):
        assert out == 'inf'
    else:
        if out == 'inf':
            assert False, 'should not be inf for these tiny values'
        else:
            assert int(out) == ans

def test_no_negative_finite(run, x):
    out = run(x).strip()
    if out == 'inf':
        return
    val = int(out)
    assert val >= 0, 'finite answer cannot be negative'

