def test_output_format(run, x):
    out = run(x).strip()
    allowed = {'need tree', 'automaton', 'array', 'both'}
    assert out in allowed, f'Output "{out}" is not one of {allowed}'

def test_need_tree_iff_not_possible(run, x):
    s, t = x.strip().split('\n')
    out = run(x).strip()
    # Compute if possible using automaton (subseq) and array (anagram)
    from collections import Counter
    is_subseq = False
    i = 0
    for c in s:
        if i < len(t) and c == t[i]:
            i += 1
    is_subseq = (i == len(t))
    is_anagram = (Counter(s) == Counter(t))
    possible = is_subseq or is_anagram or (is_subseq and is_anagram)  # actually both are enough
    # According to spec: need tree iff cannot transform even with both
    can_both = (Counter(s) >= Counter(t))  # we can delete and permute
    if out == 'need tree':
        assert not can_both, f'need tree output but transformation is possible with both'
    else:
        assert can_both, f'non-need-tree output but transformation impossible with both'

def test_automaton_implies_subsequence(run, x):
    s, t = x.strip().split('\n')
    out = run(x).strip()
    if out == 'automaton':
        # automaton means t must be a subsequence of s
        i = 0
        for c in s:
            if i < len(t) and c == t[i]:
                i += 1
        assert i == len(t), f'automaton output but t not a subsequence of s'

def test_array_implies_anagram(run, x):
    s, t = x.strip().split('\n')
    out = run(x).strip()
    from collections import Counter
    if out == 'array':
        assert Counter(s) == Counter(t), f'array output but s and t are not anagrams'

def test_both_implies_anagram_and_subseq(run, x):
    s, t = x.strip().split('\n')
    out = run(x).strip()
    from collections import Counter
    if out == 'both':
        assert Counter(s) == Counter(t), f'both output but s and t are not anagrams'
        i = 0
        for c in s:
            if i < len(t) and c == t[i]:
                i += 1
        assert i == len(t), f'both output but t not a subsequence of s'

def test_automaton_excludes_array(run, x):
    out = run(x).strip()
    # According to spec: if only array needed, automaton impossible; vice versa.
    # So automaton and array cannot both be correct for same input.
    # But the output is a single choice, so we just check that they are not both true in reality.
    s, t = x.strip().split('\n')
    from collections import Counter
    is_subseq = False
    i = 0
    for c in s:
        if i < len(t) and c == t[i]:
            i += 1
    is_subseq = (i == len(t))
    is_anagram = (Counter(s) == Counter(t))
    if is_subseq and not is_anagram:
        assert out != 'array', f'array output when automaton is possible and anagram false'
    if is_anagram and not is_subseq:
        assert out != 'automaton', f'automaton output when array is possible and subseq false'

def test_need_tree_excludes_others(run, x):
    s, t = x.strip().split('\n')
    out = run(x).strip()
    from collections import Counter
    can_both = (Counter(s) >= Counter(t))
    if not can_both:
        assert out == 'need tree', f'output should be need tree when transformation impossible'

def test_bruteforce_small(run, x):
    s, t = x.strip().split('\n')
    if len(s) <= 6 and len(t) <= 6:
        # Brute-force compute possible transformations using automaton (deletions) and array (swaps).
        # Since both can be used unlimited times, we can delete any subset and permute any remaining.
        # So possible iff multiset of s contains multiset of t.
        from collections import Counter
        possible = (Counter(s) >= Counter(t))
        if possible:
            # Determine minimal needed.
            # automaton only: t is subsequence of s AND Counter(s) != Counter(t)
            # array only: t is not subsequence AND Counter(s) == Counter(t)
            # both: t is subsequence AND Counter(s) == Counter(t) AND s != t (since s != t given)
            i = 0
            for c in s:
                if i < len(t) and c == t[i]:
                    i += 1
            is_subseq = (i == len(t))
            is_anagram = (Counter(s) == Counter(t))
            if is_subseq and not is_anagram:
                expected = 'automaton'
            elif is_anagram and not is_subseq:
                expected = 'array'
            elif is_subseq and is_anagram:
                expected = 'both'
            else:
                # possible but need both? Actually if possible and not subseq and not anagram, need both.
                # Example: s='ab', t='ba' -> is_subseq? no, is_anagram? yes -> array, covered.
                # So this case cannot happen because possible implies Counter(s) >= Counter(t).
                # If not subseq and not anagram, but possible, then need both.
                expected = 'both'
        else:
            expected = 'need tree'
        assert run(x).strip() == expected, f'bruteforce mismatch'

def test_automaton_array_mutual_exclusive(run, x):
    out = run(x).strip()
    # According to spec: if only automaton needed, array impossible; if only array needed, automaton impossible.
    # So output cannot be both 'automaton' and 'array' at same time (obviously).
    # But also if output is 'automaton', then array should not be sufficient alone.
    s, t = x.strip().split('\n')
    from collections import Counter
    is_anagram = (Counter(s) == Counter(t))
    if out == 'automaton':
        assert not is_anagram, f'automaton output but s and t are anagrams (array would suffice)'
    if out == 'array':
        i = 0
        for c in s:
            if i < len(t) and c == t[i]:
                i += 1
        is_subseq = (i == len(t))
        assert not is_subseq, f'array output but t is subsequence of s (automaton would suffice)'

def test_consistency_with_both_condition(run, x):
    s, t = x.strip().split('\n')
    out = run(x).strip()
    from collections import Counter
    is_anagram = (Counter(s) == Counter(t))
    i = 0
    for c in s:
        if i < len(t) and c == t[i]:
            i += 1
    is_subseq = (i == len(t))
    if is_anagram and is_subseq and s != t:
        assert out == 'both', f's and t are anagrams and t subsequence of s but not equal, should be both'
    if out == 'both':
        assert is_anagram and is_subseq and s != t, f'both output but preconditions not met'

