def test_answer_is_integer(run, x):
    out = run(x).strip()
    try:
        int(out)
    except ValueError:
        assert False, f'Output "{out}" is not an integer'

def test_answer_strictly_greater(run, x):
    y = int(x.strip())
    ans = int(run(x).strip())
    assert ans > y, f'Answer {ans} not > {y}'

def test_answer_has_four_digits(run, x):
    ans_str = run(x).strip()
    assert len(ans_str) == 4, f'Answer {ans_str} does not have exactly 4 digits'

def test_answer_digits_distinct(run, x):
    ans_str = run(x).strip()
    assert len(set(ans_str)) == 4, f'Answer {ans_str} has repeated digits'

def test_answer_within_range(run, x):
    ans = int(run(x).strip())
    # The problem guarantees answer exists for y ≤ 9000, so answer ≤ 9876 (max 4‑digit with distinct digits)
    assert 1000 <= ans <= 9876, f'Answer {ans} outside possible range'

def test_answer_minimality_by_bruteforce(run, x):
    y = int(x.strip())
    ans = int(run(x).strip())
    # Brute‑force the correct answer directly from spec (since y ≤ 9000, this is fast)
    for candidate in range(y + 1, 10000):
        if len(set(str(candidate))) == 4:
            correct = candidate
            break
    else:
        correct = None  # Should not happen per guarantee
    assert ans == correct, f'Answer {ans} differs from brute‑force correct {correct}'

def test_answer_no_leading_zero(run, x):
    ans_str = run(x).strip()
    assert ans_str[0] != '0', f'Answer {ans_str} has leading zero'

def test_answer_digits_all_numeric(run, x):
    ans_str = run(x).strip()
    assert ans_str.isdigit(), f'Answer {ans_str} contains non‑digit characters'

def test_answer_increasing_but_no_skip_of_valid(run, x):
    # This is a weaker check: the answer must be the smallest > y with distinct digits.
    # We can't recompute, but we can at least verify that y+1 .. ans-1 all fail distinctness.
    y = int(x.strip())
    ans = int(run(x).strip())
    for cand in range(y + 1, ans):
        if len(set(str(cand))) == 4:
            assert False, f'Found a smaller valid year {cand} that was skipped'

def test_answer_parses_as_single_token(run, x):
    out = run(x).strip()
    tokens = out.split()
    assert len(tokens) == 1, f'Output contains extra whitespace/tokens'

