def test_output_format(run, x):
    out = run(x)
    assert out in ('YES\n', 'NO\n'), f'Output must be YES or NO with newline, got {repr(out)}'

def test_necessary_condition(run, x):
    a, b = map(int, x.strip().split())
    out = run(x).strip()
    if out == 'YES':
        assert abs(a - b) <= 1, f'YES answer requires |a-b| <=1, got a={a}, b={b}'

def test_sufficient_condition(run, x):
    a, b = map(int, x.strip().split())
    out = run(x).strip()
    if abs(a - b) <= 1 and (a + b) > 0:
        assert out == 'YES', f'For a={a}, b={b} (|a-b|<=1 and a+b>0) answer must be YES, got {out}'

def test_empty_case(run, x):
    a, b = map(int, x.strip().split())
    out = run(x).strip()
    if a == 0 and b == 0:
        assert out == 'NO', f'For (0,0) answer must be NO, got {out}'

def test_brute_force_small(run, x):
    a, b = map(int, x.strip().split())
    if a + b > 30:
        return  # skip large sums
    out = run(x).strip()
    # brute force search for interval with exactly a evens, b odds
    found = False
    max_len = 2 * (a + b) + 10  # generous upper bound
    for l in range(1, max_len + 1):
        for r in range(l, max_len + 1):
            evens = (r // 2) - ((l - 1) // 2)
            odds = (r - l + 1) - evens
            if evens == a and odds == b:
                found = True
                break
        if found:
            break
    expected = 'YES' if found else 'NO'
    assert out == expected, f'For a={a}, b={b} expected {expected}, got {out}'

def test_example_1(run, x):
    if x.strip() == '2 3':
        out = run(x).strip()
        assert out == 'YES', f'For input "2 3" expected YES, got {out}'

def test_example_2(run, x):
    if x.strip() == '3 1':
        out = run(x).strip()
        assert out == 'NO', f'For input "3 1" expected NO, got {out}'

def test_positive_total_equal(run, x):
