def test_output_dimensions(run, x):
    # From the output section: 'Output n lines. Each line should contain a string consisting of m characters.'
    n, m = map(int, x.strip().split())
    output = run(x)
    lines = output.strip().split('\n')
    assert len(lines) == n, f'Expected {n} lines, got {len(lines)}'
    for line in lines:
        assert len(line) == m, f'Expected line length {m}, got {len(line)}'

def test_only_dot_and_hash(run, x):
    # From the output: empty cells are '.' and snake cells are '#'.
    output = run(x)
    lines = output.strip().split('\n')
    for line in lines:
        for ch in line:
            assert ch in '.#', f'Invalid character {ch} in output'

def test_even_rows_all_hash(run, x):
    # From the pattern: rows with index 0-based i where i%2==0 (first row is 1) are all '#'.
    n, m = map(int, x.strip().split())
    output = run(x)
    lines = output.strip().split('\n')
    for i, line in enumerate(lines):
        if i % 2 == 0:  # zero-indexed, corresponds to row 1, 3, 5, ...
            assert line == '#' * m, f'Row {i+1} should be all #'

def test_odd_rows_single_hash_right(run, x):
    # For rows where (i%4==1) zero-indexed (i.e., second row, sixth row, ...), the snake has a '#' at the last column.
    n, m = map(int, x.strip().split())
    output = run(x)
    lines = output.strip().split('\n')
    for i, line in enumerate(lines):
        if i % 4 == 1:
            assert line[-1] == '#', f'Row {i+1} should have # at last column'
            # All preceding characters must be '.'
            if m > 1:
                assert line[:-1] == '.' * (m-1), f'Row {i+1} should have dots before #'

def test_odd_rows_single_hash_left(run, x):
    # For rows where (i%4==3) zero-indexed (i.e., fourth row, eighth row, ...), the snake has a '#' at the first column.
    n, m = map(int, x.strip().split())
    output = run(x)
    lines = output.strip().split('\n')
    for i, line in enumerate(lines):
        if i % 4 == 3:
            assert line[0] == '#', f'Row {i+1} should have # at first column'
            if m > 1:
                assert line[1:] == '.' * (m-1), f'Row {i+1} should have dots after #'

def test_row_pattern_alternation(run, x):
    # The pattern cycles: all #, then single # at right, then all #, then single # at left.
    n, m = map(int, x.strip().split())
    output = run(x)
    lines = output.strip().split('\n')
    for i in range(n):
        if i % 2 == 0:
            assert lines[i] == '#' * m
        else:
            # odd row: exactly one '#', at left or right depending on i%4
            assert lines[i].count('#') == 1, f'Row {i+1} should have exactly one #'
            if i % 4 == 1:
                assert lines[i][-1] == '#'
            else:  # i % 4 == 3
                assert lines[i][0] == '#'

def test_no_extra_characters(run, x):
    # Ensure no extra whitespace (the output should not contain spaces).
    output = run(x)
    lines = output.split('\n')
    # Remove trailing empty lines from split
    lines = [line for line in lines if line != '']
    n, m = map(int, x.strip().split())
    assert len(lines) == n
    for line in lines:
        assert len(line) == m
        assert ' ' not in line, 'Space found in output'

def test_snake_continuity_implied(run, x):
    # A weaker property: the snake occupies every column in all-# rows, and exactly one column in other rows.
    n, m = map(int, x.strip().split())
    output = run(x)
    lines = output.strip().split('\n')
    for i, line in enumerate(lines):
        if i % 2 == 0:
            assert line.count('#') == m
        else:
            assert line.count('#') == 1

def test_hash_positions_consistent(run, x):
    # For odd rows, the single '#' must be at the correct edge.
    n, m = map(int, x.strip().split())
    output = run(x)
    lines = output.strip().split('\n')
    for i in range(1, n, 2):  # odd rows only
        if i % 4 == 1:
            assert lines[i].endswith('#')
        else:
            assert lines[i].startswith('#')

def test_all_cells_covered(run, x):
    # Sanity: total number of '#' cells should be at least n + (n-1)//2 (minimum plausible) and at most n*m.
    n, m = map(int, x.strip().split())
    output = run(x)
    total_hash = sum(line.count('#') for line in output.strip().split('\n'))
    # Lower bound: every even row full (m), every odd row 1 -> ceil(n/2)*m + floor(n/2)*1? Actually pattern gives exact count.
    # But we just ensure it's not trivially wrong (like all dots or all hashes).
    assert 0 < total_hash <= n*m
    # This is the weakest test; I would drop it first.

