    # collect moves from output board
    moves = []
    center = n-1
    for i in range(2*n-1):
        for j in range(2*n-1):
            if board_out[i][j] == 'x':
                dx = i - center
                dy = j - center
                moves.append((dx, dy))
    # for each 'x' in input, check if some 'o' plus some move lands there
    for i in range(n):
