def test_output_format(run, x):
    out = run(x).strip()
    assert out == '-' or all('a' <= c <= 'z' for c in out), 'Output must be a minus or lowercase letters'

def test_subsequence_of_a(run, x):
    a, b = x.strip().split('\n')
    out = run(x).strip()
    if out == '-':
        return
    i = 0
    for ch in out:
        while i < len(a) and a[i] != ch:
            i += 1
        if i >= len(a):
            assert False, f'Output {out} is not a subsequence of a={a}'
        i += 1

def test_obtainable_from_b_by_consecutive_deletion(run, x):
    a, b = x.strip().split('\n')
    out = run(x).strip()
    if out == '-':
        # empty string is obtainable by deleting all consecutive characters of b
        return
    # Check if out is a subsequence of b and characters appear in same order and consecutively except for one gap
    i = 0
    for ch in out:
        while i < len(b) and b[i] != ch:
            i += 1
        if i >= len(b):
            assert False, f'Output {out} not a subsequence of b={b}'
        i += 1
    # Now verify that the matched indices in b are consecutive except for one contiguous block of skipped characters
    # Build list of matched indices
    matched_idx = []
    i = 0
    for ch in out:
        while b[i] != ch:
            i += 1
        matched_idx.append(i)
        i += 1
    # The gaps between consecutive matched indices must be all zero except possibly one contiguous block
    gaps = [matched_idx[j+1] - matched_idx[j] - 1 for j in range(len(matched_idx)-1)]
    non_zero = [g for g in gaps if g > 0]
    if len(non_zero) > 1:
        assert False, f'Output {out} requires more than one consecutive deletion block from b={b}'

def test_deletion_block_is_single_interval(run, x):
    a, b = x.strip().split('\n')
    out = run(x).strip()
    if out == '-':
        return
    # Find if out can be obtained from b by removing one consecutive block
    # Brute force over possible start and end of deletion
    n = len(b)
    m = len(out)
    possible = False
    for del_start in range(n+1):
        for del_end in range(del_start, n+1):
            # delete indices [del_start, del_end-1]
            remaining = b[:del_start] + b[del_end:]
            if remaining == out:
                possible = True
                break
        if possible:
            break
    assert possible, f'Output {out} not obtainable from b={b} by deleting one consecutive block'

def test_length_non_negative(run, x):
    out = run(x).strip()
    if out == '-':
        assert True
    else:
        assert len(out) >= 0, 'Output length must be non-negative'

def test_no_longer_than_b(run, x):
    a, b = x.strip().split('\n')
    out = run(x).strip()
    if out == '-':
        assert len('') <= len(b)
    else:
        assert len(out) <= len(b), 'Output longer than b'

def test_bruteforce_small(run, x):
    a, b = x.strip().split('\n')
    if len(a) > 8 or len(b) > 8:  # brute force only for tiny strings
        return
    # brute force all possible consecutive deletions from b, check subsequence of a, keep longest
    best_len = -1
    best_out = ''
    n = len(b)
    for del_start in range(n+1):
        for del_end in range(del_start, n+1):
            cand = b[:del_start] + b[del_end:]
            # check if cand is subsequence of a
            i = 0
            ok = True
            for ch in cand:
                while i < len(a) and a[i] != ch:
                    i += 1
                if i >= len(a):
                    ok = False
                    break
                i += 1
            if ok and len(cand) > best_len:
                best_len = len(cand)
                best_out = cand
    if best_len == 0:
        best_out = '-'
    out = run(x).strip()
    assert out == best_out, f'For small input, optimal output is {best_out}, got {out}'

def test_monotonic_length_with_bruteforce_prefix(run, x):
    a, b = x.strip().split('\n')
    # For small strings, we can brute force length of optimal answer
    if len(a) <= 6 and len(b) <= 6:
        # compute optimal length by brute force
        best_len = 0
        n = len(b)
        for del_start in range(n+1):
            for del_end in range(del_start, n+1):
                cand = b[:del_start] + b[del_end:]
                i = 0
                ok = True
                for ch in cand:
                    while i < len(a) and a[i] != ch:
                        i += 1
                    if i >= len(a):
                        ok = False
                        break
                    i += 1
                if ok and len(cand) > best_len:
                    best_len = len(cand)
        out = run(x).strip()
        out_len = 0 if out == '-' else len(out)
        assert out_len == best_len, f'Length mismatch: optimal {best_len}, got {out_len}'

def test_answer_is_subsequence_of_b(run, x):
    a, b = x.strip().split('\n')
    out = run(x).strip()
    if out == '-':
        return
    i = 0
    for ch in out:
        while i < len(b) and b[i] != ch:
            i += 1
        if i >= len(b):
            assert False, f'Output {out} not a subsequence of b={b}'
        i += 1

def test_no_extra_characters(run, x):
    out = run(x).strip()
    # output must be exactly one line, no extra whitespace
    lines = run(x).split('\n')
    assert len(lines) <= 2, 'More than one output line'
    # first line should be the output, possible trailing newline is okay
    if len(lines) == 2:
        assert lines[1] == '', 'Extra content after first line'

