def test_output_non_negative_integer(run, x):
    out = run(x).strip()
    val = int(out)
    assert val >= 0

def test_output_fits_64bit(run, x):
    out = run(x).strip()
    val = int(out)
    # max possible subsegments = n*(n+1)//2 ≤ 2e5 * 2e5 / 2 = 2e10, fits in 64 bits
    assert val <= 2_000_010_000_000_000

def test_single_element_1_k1(run, x):
    lines = x.strip().split('\n')
    nk = list(map(int, lines[0].split()))
    if len(lines) < 2:
        return
    a = list(map(int, lines[1].split()))
    if nk[0] == 1 and nk[1] == 1:
        if a[0] == 1:
            assert int(run(x).strip()) == 1
        else:
            assert int(run(x).strip()) == 0

def test_all_ones_k1(run, x):
    lines = x.strip().split('\n')
    nk = list(map(int, lines[0].split()))
    if len(lines) < 2:
        return
    a = list(map(int, lines[1].split()))
    n, k = nk
    if k == 1 and all(v == 1 for v in a):
        expected = n * (n + 1) // 2
        assert int(run(x).strip()) == expected

def test_no_subsegment_if_product_always_larger(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    nk = list(map(int, lines[0].split()))
    a = list(map(int, lines[1].split()))
    n, k = nk
    # If every a_i > 1 and k = 1, product >= 2^len > sum for len ≥ 2.
    # For k > 1, condition is stricter.
    # A safe bound: if min(a) > 1 and k == 1, then any subsegment of length ≥2
    # cannot satisfy product == sum, so answer ≤ n (single‑element segments).
    if k == 1 and all(v > 1 for v in a):
        ans = int(run(x).strip())
        assert ans <= n

def test_single_element_equal_k(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    nk = list(map(int, lines[0].split()))
    a = list(map(int, lines[1].split()))
    n, k = nk
    if n == 1 and a[0] == k:
        assert int(run(x).strip()) == 1

def test_two_large_equal_k1(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    nk = list(map(int, lines[0].split()))
    a = list(map(int, lines[1].split()))
    n, k = nk
    if n == 2 and k == 1 and a[0] == a[1] and a[0] > 1:
        # product/sum = a / 2 > 1 for a>2, never 1.
        # Only possible subsegments are single elements, which give a != 1.
        # So answer must be 0.
