def test_output_format(run, x):
    out = run(x).strip()
    if out == '-1':
        return
    assert out.isdigit() or (out[0]=='-' and out[1:].isdigit())
    val = int(out)
    assert val >= 0

def test_no_negative_except_minus_one(run, x):
    out = run(x).strip()
    if out == '-1':
        return
    val = int(out)
    assert val >= 0

def test_integer_output(run, x):
    out = run(x).strip()
    try:
        int(out)
    except ValueError:
        assert False, 'Output must be an integer'

def test_upper_bound(run, x):
    lines = x.strip().split('\n')
    x0,y0,x1,y1 = map(int, lines[0].split())
    out = run(x).strip()
    if out == '-1':
        return
    moves = int(out)
    # King can always move one step in Chebyshev distance, but a trivial bound is Manhattan distance
    max_dist = abs(x0-x1) + abs(y0-y1)
    assert moves <= max_dist

def test_adjacent_ones(run, x):
    lines = x.strip().split('\n')
    x0,y0,x1,y1 = map(int, lines[0].split())
    if max(abs(x0-x1), abs(y0-y1)) == 1:
        # adjacent cells, check that both are allowed (guaranteed by problem statement)
        out = run(x).strip()
        if out == '-1':
            assert False, 'Adjacent allowed cells must be reachable in 1 move'
        else:
            assert int(out) == 1

def test_same_cell_zero(run, x):
    lines = x.strip().split('\n')
    x0,y0,x1,y1 = map(int, lines[0].split())
    if x0==x1 and y0==y1:
        out = run(x).strip()
        assert out == '0'

def test_small_bruteforce(run, x):
    lines = x.strip().split('\n')
    x0,y0,x1,y1 = map(int, lines[0].split())
    n = int(lines[1])
    total_cells = 0
    rows = {}
    for i in range(n):
        r,a,b = map(int, lines[2+i].split())
        total_cells += b - a + 1
        rows.setdefault(r, []).append((a,b))
    # If total allowed cells <= 1000, we can brute-force BFS
    if total_cells > 1000:
        return
    from collections import deque
    allowed = set()
    for r, segs in rows.items():
        for a,b in segs:
            for col in range(a, b+1):
                allowed.add((r, col))
    if (x0,y0) not in allowed or (x1,y1) not in allowed:
        return  # problem guarantees they are allowed
    q = deque()
    dist = {(x0,y0): 0}
    q.append((x0,y0))
    dx = [-1,0,1,-1,1,-1,0,1]
    dy = [-1,-1,-1,0,0,1,1,1]
    while q:
        cx,cy = q.popleft()
        d = dist[(cx,cy)]
        for k in range(8):
            nx,ny = cx+dx[k], cy+dy[k]
            if (nx,ny) in allowed and (nx,ny) not in dist:
                dist[(nx,ny)] = d+1
                q.append((nx,ny))
    expected = dist.get((x1,y1), -1)
    out = run(x).strip()
    if expected == -1:
        assert out == '-1'
    else:
        assert int(out) == expected

def test_lower_bound_chebyshev(run, x):
    lines = x.strip().split('\n')
    x0,y0,x1,y1 = map(int, lines[0].split())
    out = run(x).strip()
    if out == '-1':
        return
    moves = int(out)
    cheb = max(abs(x0-x1), abs(y0-y1))
    assert moves >= cheb

