    n = int(lines[1])
    total_cells = 0
    rows = {}
    for i in range(n):
        r,a,b = map(int, lines[2+i].split())
        total_cells += b - a + 1
        rows.setdefault(r, []).append((a,b))
    if total_cells > 1000:
        return
    allowed = set()
    for r, segs in rows.items():
        for a,b in segs:
            for col in range(a, b+1):
                allowed.add((r, col))
    from collections import deque
    q = deque()
    dist = {(x0,y0): 0}
    q.append((x0,y0))
    dx = [-1,0,1,-1,1,-1,0,1]
    dy = [-1,-1,-1,0,0,1,1,1]
    while q:
        cx,cy = q.popleft()
        d = dist[(cx,cy)]
        for k in range(8):
            nx,ny = cx+dx[k], cy+dy[k]
            if (nx,ny) in allowed and (nx,ny) not in dist:
                dist[(nx,ny)] = d+1
                q.append((nx,ny))
    reachable = (x1,y1) in dist
    out = run(x).strip()
    if reachable:
        assert out != '-1'
    else:
        assert out == '-1'

def test_zero_not_allowed(run, x):
    lines = x.strip().split('\n')
