def test_answer_non_negative(run, x):
    ans = int(run(x).strip())
    assert ans >= 0

def test_answer_leq_n(run, x):
    n = int(x.strip())
    ans = int(run(x).strip())
    assert ans <= n

def test_answer_integer(run, x):
    s = run(x).strip()
    # check it's an integer without leading zeros unless it's '0'
    if s == '0':
        return
    assert s.isdigit() and s[0] != '0'
    # ensure conversion works
    int(s)

def test_brute_force_small_n(run, x):
    n = int(x.strip())
    if n > 10**5:
        return  # skip large n
    ans = int(run(x).strip())
    # brute force correct answer
    cnt = 0
    for i in range(1, n + 1):
        if i % 2 != 0 and i % 3 != 0 and i % 5 != 0 and i % 7 != 0:
            cnt += 1
    assert ans == cnt

def test_periodicity(run, x):
    n = int(x.strip())
    ans = int(run(x).strip())
    # compute using periodicity modulo 210
    block = n // 210
    r = n % 210
    # count numbers in [1,r] not divisible by 2,3,5,7
    rem_cnt = 0
    for i in range(1, r + 1):
        if i % 2 != 0 and i % 3 != 0 and i % 5 != 0 and i % 7 != 0:
            rem_cnt += 1
    correct = block * 48 + rem_cnt
    assert ans == correct

def test_multiple_of_210(run, x):
    n = int(x.strip())
    if n % 210 != 0:
        return
    ans = int(run(x).strip())
    correct = (n // 210) * 48
    assert ans == correct

