        return
    ans = int(run(x).strip())
    assert ans == 1

def test_n_equals_3(run, x):
    n = int(x.strip())
    if n != 3:
        return
    ans = int(run(x).strip())
    assert ans == 1

def test_n_equals_210(run, x):
    n = int(x.strip())
    if n != 210:
        return
    ans = int(run(x).strip())
    assert ans == 48

