def test_output_is_integer(run, x):
    out = run(x)
    assert out.strip().lstrip('-').isdigit(), 'Output must be an integer'


def test_answer_ge_min_possible(run, x):
    lines = x.strip().split('\n')
    n, k = map(int, lines[0].split())
    min_joy = None
    for line in lines[1:1+n]:
        f, t = map(int, line.split())
        joy = f - max(0, t - k)
        if min_joy is None or joy < min_joy:
            min_joy = joy
    ans = int(run(x).strip())
    assert ans >= min_joy, f'Answer {ans} < minimum possible joy {min_joy}'


def test_single_restaurant_exact(run, x):
    lines = x.strip().split('\n')
    n, k = map(int, lines[0].split())
    if n == 1:
        f, t = map(int, lines[1].split())
        expected = f - max(0, t - k)
        ans = int(run(x).strip())
        assert ans == expected, f'Single restaurant must yield joy {expected}, got {ans}'


def test_all_t_le_k_max_f(run, x):
    lines = x.strip().split('\n')
    n, k = map(int, lines[0].split())
    all_t_le_k = True
    max_f = None
    for line in lines[1:1+n]:
        f, t = map(int, line.split())
        if max_f is None or f > max_f:
            max_f = f
        if t > k:
            all_t_le_k = False
    if all_t_le_k:
        ans = int(run(x).strip())
        assert ans == max_f, f'All t_i ≤ k ⇒ answer must be max f_i = {max_f}, got {ans}'


def test_all_t_ge_k_max_joy_formula(run, x):
    lines = x.strip().split('\n')
    n, k = map(int, lines[0].split())
    all_t_ge_k = True
    max_joy = None
    for line in lines[1:1+n]:
        f, t = map(int, line.split())
        if t < k:
            all_t_ge_k = False
        joy = f - (t - k)
        if max_joy is None or joy > max_joy:
            max_joy = joy
    if all_t_ge_k:
        ans = int(run(x).strip())
        assert ans == max_joy, f'All t_i ≥ k ⇒ answer must be max (f_i - (t_i - k)) = {max_joy}, got {ans}'


def test_answer_le_max_f(run, x):
    lines = x.strip().split('\n')
    n, k = map(int, lines[0].split())
    max_f = None
    for line in lines[1:1+n]:
        f, t = map(int, line.split())
        if max_f is None or f > max_f:
            max_f = f
    ans = int(run(x).strip())
    assert ans <= max_f, f'Answer {ans} > max f_i {max_f} impossible'


def test_answer_ge_min_joy(run, x):
    lines = x.strip().split('\n')
