        if min_joy is None or joy < min_joy:
            min_joy = joy
    ans = int(run(x).strip())
    assert ans >= min_joy, f'Answer {ans} < min possible joy {min_joy}'


def test_answer_in_extreme_bounds(run, x):
    lines = x.strip().split('\n')
    n, k = map(int, lines[0].split())
    max_f = 0
    min_joy = 10**20
    for line in lines[1:1+n]:
        f, t = map(int, line.split())
        if f > max_f:
