        joy = f - max(0, t - k)
        if joy < min_joy:
            min_joy = joy
    lower = min_joy
    upper = max_f
    ans = int(run(x).strip())
    assert lower <= ans <= upper, f'Answer {ans} outside possible range [{lower}, {upper}]'


