      "name": "test_brute_force_for_small_n",
      "source": "def test_brute_force_for_small_n(run, x):
    import sys
    sys.setrecursionlimit(10**6)
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    if n > 8:
        return  # too big for brute force
    s = lines[1].strip()
    edges = []
    for i in range(2, 2 + m):
        a, b = map(int, lines[i].split())
        edges.append((a-1, b-1))
    # Build graph
    adj = [[] for _ in range(n)]
    for a, b in edges:
        adj[a].append(b)
    # Check for cycles (self-loop already covered earlier)
    visited = [0]*n
    def dfs_cycle(u):
        visited[u] = 1
        for v in adj[u]:
            if visited[v] == 1:
                return True
            elif visited[v] == 0 and dfs_cycle(v):
                return True
        visited[u] = 2
