            has_cycle = True
            break
    if has_cycle:
        assert run(x).strip() == '-1', "Small graph has cycle, must output -1"
        return
    # No cycle, brute force DP over DAG (topological order)
    from collections import deque
    indeg = [0]*n
    for a, b in edges:
        indeg[b] += 1
    q = deque([i for i in range(n) if indeg[i]==0])
    topo = []
    while q:
        u = q.popleft()
        topo.append(u)
        for v in adj[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                q.append(v)
    if len(topo) != n:
        # still cycle
        assert run(x).strip() == '-1'
        return
    dp = [[0]*26 for _ in range(n)]
    best = 0
    for u in topo:
        c = ord(s[u]) - ord('a')
        dp[u][c] += 1
        best = max(best, dp[u][c])
        for v in adj[u]:
            for k in range(26):
                dp[v][k] = max(dp[v][k], dp[u][k])
                best = max(best, dp[v][k])
