def test_output_format(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    first_line = x.split('\n')[0]
    n, m, k = map(int, first_line.split())
    assert len(lines) == k, f'Expected {k} lines, got {len(lines)}'

def test_each_line_is_integer(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    for line in lines:
        int(line.strip())

def test_answer_non_negative(run, x):
    out = run(x)
    for line in out.strip().split('\n'):
        assert int(line.strip()) >= 0

def test_answer_not_exceeds_wall_limit(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    max_walls = 2 * (n-2) * (m-2)  # interior cells each have up to 4 walls but each wall counted twice
    # Actually each interior empty cell adjacent to a wall adds 1 per adjacent '*'.
    # Upper bound: every empty cell is surrounded by 4 walls, but each wall shared by 2 cells -> total pictures = 2*(n-2)*(m-2) + (perimeter interior walls?)
    # Simpler safe bound: total cells n*m, each '*' contributes up to 4 pictures, each '.' contributes up to 4 pictures.
    # But each picture is counted once. Maximum pictures ≤ 2*n*m (since each of n*m cells has ≤4 adjacent walls, each wall counted twice across cells).
    # Use a very safe bound: 4 * n * m.
    max_bound = 4 * n * m
    out = run(x)
    for line in out.strip().split('\n'):
        val = int(line.strip())
        assert val <= max_bound

def test_small_case_bruteforce(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    if n > 20 or m > 20 or k > 10:
        return  # skip large cases
    grid = [list(line) for line in lines[1:1+n]]
    queries = [list(map(int, line.split())) for line in lines[1+n:1+n+k]]
    from collections import deque
    for (sx, sy) in queries:
        sx -= 1; sy -= 1
        visited = [[False]*m for _ in range(n)]
        q = deque()
        q.append((sx, sy))
        visited[sx][sy] = True
        pictures = 0
        while q:
            x, y = q.popleft()
            for dx, dy in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx, ny = x+dx, y+dy
                if 0 <= nx < n and 0 <= ny < m:
                    if grid[nx][ny] == '*':
                        pictures += 1
                    elif not visited[nx][ny]:
                        visited[nx][ny] = True
                        q.append((nx, ny))
        out = run(x)
        vals = list(map(int, out.strip().split('\n')))
        idx = queries.index((sx+1, sy+1))
        assert vals[idx] == pictures

