    grid = [list(line) for line in lines[1:1+n]]
    queries = [tuple(map(int, line.split())) for line in lines[1+n:1+n+k]]
    out = run(x)
    ans = list(map(int, out.strip().split('\n')))
    for idx, (sx, sy) in enumerate(queries):
        sx -= 1; sy -= 1
        immediate = 0
        for dx, dy in [(1,0),(-1,0),(0,1),(0,-1)]:
            nx, ny = sx+dx, sy+dy
