                immediate += 1
        assert ans[idx] >= immediate

def test_no_output_for_nonempty_start(run, x):
    # Starting cells are guaranteed empty, so answer should be computed.
    # Just ensure output lines are present (already covered).
    pass

def test_answer_integer_range(run, x):
    out = run(x)
    for line in out.strip().split('\n'):
        val = int(line.strip())
        # According to constraints, n,m up to 1000, max pictures ≤ 4*10^6.
        assert 0 <= val <= 10**7

