def test_integer_is_leaf(run, x):
    out = run(x).strip()
    if out in ('Game cheated!', 'Data not sufficient!'):
        return
    h = int(x.split()[0])
    leaf_min = 2**(h-1)
    leaf_max = 2**h - 1
    num = int(out)
    assert leaf_min <= num <= leaf_max

def test_leaf_satisfies_yes_answers_for_small_h(run, x):
    import sys
    out = run(x).strip()
    if out in ('Game cheated!', 'Data not sufficient!'):
        return
    h, qstr = x.strip().split('\n', 1)
    h = int(h)
    if h > 20:
        return  # brute force too heavy
    lines = qstr.strip().split('\n')
    q = 0 if lines == [''] else len(lines)
    leaves = list(range(2**(h-1), 2**h))
    yes_constraints = []
    no_constraints = []
    for line in lines:
        if not line:
            continue
        i, L, R, a = map(int, line.split())
        if a == 1:
            yes_constraints.append((i, L, R))
        else:
            no_constraints.append((i, L, R))
    possible = []
    for leaf in leaves:
        ok = True
        for i, L, R in yes_constraints:
            # ancestor at level i
            anc = leaf
            for _ in range(h - i):
                anc //= 2
            if not (L <= anc <= R):
                ok = False
                break
        if not ok:
            continue
        for i, L, R in no_constraints:
            anc = leaf
            for _ in range(h - i):
                anc //= 2
            if L <= anc <= R:
                ok = False
                break
        if ok:
            possible.append(leaf)
    if len(possible) == 1:
        assert int(out) == possible[0]
    else:
        # if multiple possible, output cannot be a single leaf unless contradictions exist
        # but if output is a leaf, it must be in possible set
        assert int(out) in possible

def test_no_contradiction_if_output_is_leaf(run, x):
    import sys
    out = run(x).strip()
    if out in ('Game cheated!', 'Data not sufficient!'):
        return
    h, qstr = x.strip().split('\n', 1)
    h = int(h)
    lines = qstr.strip().split('\n')
    q = 0 if lines == [''] else len(lines)
    # just ensure leaf satisfies each question (same as above but lighter)
    leaf = int(out)
    for line in lines:
        if not line:
            continue
        i, L, R, a = map(int, line.split())
        anc = leaf
        for _ in range(h - i):
            anc //= 2
        if a == 1:
            assert L <= anc <= R, f'Leaf {leaf} fails yes constraint {i} {L} {R} with ancestor {anc}'
        else:
            assert not (L <= anc <= R), f'Leaf {leaf} fails no constraint {i} {L} {R} with ancestor {anc}'

def test_leaf_index_parity(run, x):
    out = run(x).strip()
    if out in ('Game cheated!', 'Data not sufficient!'):
