tests_src:
def test_output_non_negative(run, x):
    out = run(x).strip()
    val = int(out)
    assert val >= 0

def test_output_at_most_n_minus_one(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0].split()[0])
    out = run(x).strip()
    val = int(out)
    assert val <= n - 1

def test_output_at_least_star_diameter(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    if m != n-1:
        return  # Not a tree, skip
    deg = [0] * n
    for i in range(1, m+1):
        a, b = map(int, lines[i].split())
        deg[a-1] += 1
        deg[b-1] += 1
    center_candidates = [i for i, d in enumerate(deg) if d > 1]
    if not center_candidates:
        if n == 1:
            return
        # path graph
        return
    # star: one vertex with degree n-1, others degree 1
    if max(deg) == n-1 and min(deg) == 1:
        out = int(run(x).strip())
        assert out >= 2 if n > 2 else out >= 1

def test_output_at_least_one_if_connected_n_gt_one(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    if n > 1 and m >= n-1:  # connected (since valid system)
        out = int(run(x).strip())
        assert out >= 1

def test_brute_force_diameter_small(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    if n > 20:
        return  # skip for large graphs
    adj = [[] for _ in range(n)]
    for i in range(1, m+1):
        a, b = map(int, lines[i].split())
        adj[a-1].append(b-1)
        adj[b-1].append(a-1)
    from collections import deque
    def bfs(start):
        dist = [-1]*n
        q = deque([start])
        dist[start]=0
        while q:
            u=q.popleft()
            for v in adj[u]:
                if dist[v]==-1:
                    dist[v]=dist[u]+1
                    q.append(v)
        return max(dist)
    diam = max(bfs(i) for i in range(n))
    out = int(run(x).strip())
    assert out == diam

def test_output_is_integer(run, x):
    out = run(x).strip()
    try:
        int(out)
    except ValueError:
        assert False

def test_output_at_least_longest_path_lower_bound(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    adj = [[] for _ in range(n)]
    for i in range(1, m+1):
        a, b = map(int, lines[i].split())
        adj[a-1].append(b-1)
        adj[b-1].append(a-1)
    # compute longest simple path via DFS for small n
    if n > 15:
        return
    from functools import lru_cache
    best = 0
    for start in range(n):
        stack = [(start, 1 << start, 0)]
        while stack:
            u, mask, length = stack.pop()
            if length > best:
                best = length
            for v in adj[u]:
                if not (mask >> v) & 1:
                    stack.append((v, mask | (1 << v), length + 1))
    out = int(run(x).strip())
    assert out >= best

def test_output_upper_bound_n_minus_one(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    out = int(run(x).strip())
    assert out <= n - 1

def test_output_consistent_with_degree_one(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    if n <= 2:
        return
    deg = [0]*n
    for i in range(1, m+1):
        a, b = map(int, lines[i].split())
        deg[a-1] += 1
        deg[b-1] += 1
    if any(d == 0 for d in deg):
        return  # shouldn't happen (connected)
    out = int(run(x).strip())
    # If there is a leaf, diameter >= distance between two leaves.
    # Minimal case: star -> diameter 2.
    # So output should be at least 1 for n>1, already tested.
    # This is a placeholder for a more refined check.
    # Actually, we can compute a lower bound via BFS from a leaf.
    leaves = [i for i, d in enumerate(deg) if d == 1]
    if leaves:
        from collections import deque
        adj = [[] for _ in range(n)]
        for i in range(1, m+1):
            a, b = map(int, lines[i].split())
            adj[a-1].append(b-1)
            adj[b-1].append(a-1)
        def bfs(start):
            dist = [-1]*n
            q = deque([start])
            dist[start]=0
            while q:
                u=q.popleft()
                for v in adj[u]:
                    if dist[v]==-1:
                        dist[v]=dist[u]+1
                        q.append(v)
            return max(dist)
        lower = bfs(leaves[0])
        assert out >= lower

def test_output_non_negative_and_small(run, x):
    out = run(x).strip()
    val = int(out)
    assert 0 <= val <= 100000  # n <= 100000, diameter <= n-1

