{
  "rationale": "Each test checks a necessary condition that any correct answer must satisfy, derived directly from the problem statement. They avoid reasoning about the correct answer or using properties not guaranteed. The tests focus on: output format validity, trivial cases, and invariants like lamp coverage counts and the fact that at least one switch can be ignored only if no lamp depends uniquely on that switch. The first test to drop would be test_always_yes_or_no because it's the weakest—it only ensures the output is a valid YES/NO string, which is trivial but catches malformed output. The stronger tests rely on the condition that if a lamp is uniquely controlled by a switch, that switch cannot be ignored; this is directly implied by the problem's logic.",
  "tests": [
    {
      "name": "test_always_yes_or_no",
      "source": "def test_always_yes_or_no(run, x):
    out = run(x).strip()
    assert out in ('YES', 'NO'), f'Output must be YES or NO, got {out!r}'"
    },
    {
      "name": "test_empty_input_trivial",
      "source": "def test_empty_input_trivial(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    if n == 1:
        # With one switch, ignoring it means pressing 0 switches.
        # But statement guarantees pressing all n switches turns all lamps on.
        # If n=1, pressing the only switch must turn all lamps on.
        # If we ignore it, we press 0 switches -> all lamps off -> answer must be NO.
        out = run(x).strip()
        assert out == 'NO', f'For n=1 answer must be NO, got {out}'"
    },
    {
      "name": "test_large_n_trivial_bounds",
      "source": "def test_large_n_trivial_bounds(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    out = run(x).strip()
    if n == 1:
        assert out == 'NO', f'n=1 must output NO'
    if m == 0:
        # m can't be 0 because pressing all switches turns all lamps on, but lamps exist.
        pass"
    },
    {
      "name": "test_yes_implies_some_switch_not_unique",
      "source": "def test_yes_implies_some_switch_not_unique(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    a = [list(map(int, list(lines[i+1].strip()))) for i in range(n)]
    out = run(x).strip()
    if out == 'YES':
        # There must exist a switch that is not the sole controller of any lamp.
        # Compute for each lamp if it has a unique controller.
        unique_controller = [None] * m
        for lamp in range(m):
            cnt = 0
            last = -1
            for switch in range(n):
                if a[switch][lamp]:
                    cnt += 1
                    last = switch
            if cnt == 1:
                unique_controller[lamp] = last
        # Switches that are unique for some lamp cannot be ignored.
        forbidden = set(unique_controller) - {None}
        # At least one switch not in forbidden must exist.
        possible = [i for i in range(n) if i not in forbidden]
        assert len(possible) > 0, 'YES output but every switch uniquely controls some lamp'"
    },
    {
      "name": "test_no_implies_all_switches_unique_for_some_lamp",
      "source": "def test_no_implies_all_switches_unique_for_some_lamp(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    a = [list(map(int, list(lines[i+1].strip()))) for i in range(n)]
    out = run(x).strip()
    if out == 'NO':
        # Every switch must be the unique controller for at least one lamp.
        # Compute for each lamp if it has a unique controller.
        unique_controller = [None] * m
        for lamp in range(m):
            cnt = 0
            last = -1
            for switch in range(n):
                if a[switch][lamp]:
                    cnt += 1
                    last = switch
            if cnt == 1:
                unique_controller[lamp] = last
        forbidden = set(unique_controller) - {None}
        # Every switch must be in forbidden.
        for switch in range(n):
            if switch not in forbidden:
                # This switch could be ignored, so answer should be YES.
                # But we got NO, contradiction unless n==1 (already handled).
                if n > 1:
                    assert False, f'NO output but switch {switch} is not uniquely needed'"
    },
    {
      "name": "test_output_length",
      "source": "def test_output_length(run, x):
    out = run(x).strip()
    assert len(out) in (3, 4), f'Output length must be 3 (YES) or 4 (NO), got {len(out)}'"
    },
    {
      "name": "test_brute_force_small",
      "source": "def test_brute_force_small(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    if n <= 10 and m <= 10:
        a = [list(map(int, list(lines[i+1].strip()))) for i in range(n)]
        # Brute force check each switch.
        possible = False
        for ignore in range(n):
            covered = [False] * m
            for switch in range(n):
                if switch == ignore:
                    continue
                for lamp in range(m):
                    if a[switch][lamp]:
                        covered[lamp] = True
            if all(covered):
                possible = True
                break
        expected = 'YES' if possible else 'NO'
        out = run(x).strip()
        assert out == expected, f'Brute force says {expected}, got {out}'"
    },
    {
      "name": "test_all_switches_cover_all_lamps",
      "source": "def test_all_switches_cover_all_lamps(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    a = [list(map(int, list(lines[i+1].strip()))) for i in range(n)]
    # Guarantee from statement: pressing all switches turns all lamps on.
    # So for each lamp, at least one switch has a 1.
    for lamp in range(m):
        cnt = sum(a[switch][lamp] for switch in range(n))
        assert cnt >= 1, f'Lamp {lamp} not covered by any switch'
    # This test always passes if input follows guarantees, no assert on output."
    },
    {
      "name": "test_ignore_switch_redundancy_invariant",
      "source": "def test_ignore_switch_redundancy_invariant(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    a = [list(map(int, list(lines[i+1].strip()))) for i in range(n)]
    out = run(x).strip()
    # Compute for each lamp how many switches control it.
    lamp_counts = [sum(a[switch][lamp] for switch in range(n)) for lamp in range(m)]
    # If any lamp has count 1, that unique switch cannot be ignored.
    unique_switches = set()
    for lamp in range(m):
        if lamp_counts[lamp] == 1:
            for switch in range(n):
                if a[switch][lamp]:
                    unique_switches.add(switch)
    # If all switches are in unique_switches, answer must be NO (unless n==1 handled earlier).
    if n > 1 and len(unique_switches) == n:
        assert out == 'NO', f'All switches uniquely control some lamp, answer must be NO, got {out}'"
    },
    {
      "name": "test_yes_implies_switch_exists",
      "source": "def test_yes_implies_switch_exists(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    a = [list(map(int, list(lines[i+1].strip()))) for i in range(n)]
    out = run(x).strip()
    if out == 'YES':
        # There must be at least one switch that is not uniquely required.
        # Compute unique controllers.
