    @lru_cache(None)
    def win(state):
        sorted_state = tuple(sorted(state))
        if all(v == 0 for v in sorted_state):
            return False  # current player loses because no move
        # try each pile
        for i, v in enumerate(sorted_state):
            if v == 0:
                continue
            new_state = list(sorted_state)
            new_state[i] = v - 1
            new_state = tuple(sorted(new_state))
            # check if new_state has any two equal piles
            if any(new_state[j] == new_state[j+1] for j in range(len(new_state)-1)):
