tests_src:
def test_output_format(run, x):
    out = run(x).strip()
    assert out == 'Yes' or out == 'No', f'Invalid output: {repr(out)}'

def test_trivial_multiple_of_a(run, x):
    a, b, c = map(int, x.strip().split())
    if c % a == 0:
        out = run(x).strip()
        assert out == 'Yes', f'c divisible by a, expected Yes, got {out}'

def test_trivial_multiple_of_b(run, x):
    a, b, c = map(int, x.strip().split())
    if c % b == 0:
        out = run(x).strip()
        assert out == 'Yes', f'c divisible by b, expected Yes, got {out}'

def test_small_c_less_than_a_and_b(run, x):
    a, b, c = map(int, x.strip().split())
    if c < a and c < b and c != 0:
        out = run(x).strip()
        assert out == 'No', f'c less than both a and b (and c>=1), expected No, got {out}'

def test_a_equals_b_one(run, x):
    a, b, c = map(int, x.strip().split())
    if a == 1 and b == 1:
        out = run(x).strip()
        assert out == 'Yes', f'a=b=1, any c>=1 is Yes, got {out}'

def test_a_equals_b_not_one(run, x):
    a, b, c = map(int, x.strip().split())
    if a == b and a != 1:
        out = run(x).strip()
        if c % a == 0:
            assert out == 'Yes', f'a=b, c divisible, expected Yes, got {out}'
        else:
            assert out == 'No', f'a=b, c not divisible, expected No, got {out}'

def test_c_zero_not_possible(run, x):
    # c is at least 1 per constraints, so answer can't be Yes for c=0.
    # Not directly applicable to given inputs, but keeps invariant.
    pass

def test_gcd_divisibility(run, x):
    import math
    a, b, c = map(int, x.strip().split())
    g = math.gcd(a, b)
    if c % g != 0:
        out = run(x).strip()
        assert out == 'No', f'c not divisible by gcd(a,b), expected No, got {out}'

def test_brute_small_c(run, x):
    a, b, c = map(int, x.strip().split())
    if c <= 1000:  # keep it fast
        possible = False
        for i in range(c // a + 1):
            if (c - a * i) % b == 0:
                possible = True
                break
        out = run(x).strip()
        if possible:
            assert out == 'Yes', f'Brute says Yes, got {out}'
        else:
            assert out == 'No', f'Brute says No, got {out}'

def test_output_case(run, x):
    out = run(x).strip()
    assert out in ('Yes', 'No'), f'Output must be exactly Yes or No, got {repr(out)}'

