def test_output_format(run, x):
    output = run(x).strip()
    # Must be a single line with n integers
    parts = output.split()
    lines = [line for line in output.split('\n') if line.strip()]
    assert len(lines) == 1, 'Output must be a single line'
    n = int(x.split('\n')[0].strip())
    assert len(parts) == n, f'Expected {n} integers, got {len(parts)}'
    for p in parts:
        assert p.isdigit() or (p[0] == '-' and p[1:].isdigit()), f'Not an integer: {p}'
        val = int(p)
        assert 1 <= val <= 10**9, f'Value {val} out of range'


def test_positive_integers(run, x):
    output = run(x).strip()
    parts = output.split()
    for p in parts:
        val = int(p)
        assert val > 0, f'Value {val} not positive'


def test_diagonal_zero(run, x):
    # The input diagonal is zero; reconstructed a_i * a_i should not be zero.
    # But the task guarantees a_i positive, so a_i * a_i > 0.
    # So we only check that our reconstructed a_i are positive (covered elsewhere).
    pass


def test_consistency_first_row(run, x):
    # Parse input
    lines = x.strip().split('\n')
    n = int(lines[0])
    M = [list(map(int, lines[i+1].split())) for i in range(n)]
    output = run(x).strip()
    a = list(map(int, output.split()))
    assert len(a) == n
    # For i=0, j from 1 to n-1, M[0][j] should equal a[0] * a[j]
    for j in range(1, n):
        expected = a[0] * a[j]
        if M[0][j] != expected:
            # Allow rounding? No, exact equality required.
            assert False, f'M[0][{j}] = {M[0][j]} != a0*aj = {expected}'


def test_consistency_second_row(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    M = [list(map(int, lines[i+1].split())) for i in range(n)]
    output = run(x).strip()
    a = list(map(int, output.split()))
    for j in range(n):
        if j == 1:
            continue  # diagonal is zero
        expected = a[1] * a[j]
        if M[1][j] != expected:
            assert False, f'M[1][{j}] = {M[1][j]} != a1*aj = {expected}'


def test_consistency_all_pairs(run, x):
    # Check a few random pairs (to keep test fast)
    import sys
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n > 20:  # Too many to check all, sample
        pairs_to_check = [(i, j) for i in range(n) for j in range(i+1, n)][:100]
    else:
        pairs_to_check = [(i, j) for i in range(n) for j in range(i+1, n)]
    M = [list(map(int, lines[i+1].split())) for i in range(n)]
    output = run(x).strip()
    a = list(map(int, output.split()))
    for i, j in pairs_to_check:
        expected = a[i] * a[j]
        if M[i][j] != expected:
            assert False, f'M[{i}][{j}] = {M[i][j]} != a{i}*a{j} = {expected}'


def test_bruteforce_small(run, x):
    # Only run for n <= 7 (since given inputs are small)
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n > 7:
        return
    M = [list(map(int, lines[i+1].split())) for i in range(n)]
    output = run(x).strip()
    a = list(map(int, output.split()))
    # Brute-force search for any sequence b that matches M
    # Since a_i positive integers up to 10^9, but n small, we can deduce from first row.
    # For each possible a0 divisor of M[0][1], compute others.
    val01 = M[0][1]
    candidates = []
    for d in range(1, int(val01**0.5)+1):
        if val01 % d == 0:
            candidates.append(d)
            if d != val01 // d:
                candidates.append(val01 // d)
    found = False
    for a0 in candidates:
        ok = True
        b = [0]*n
        b[0] = a0
        for j in range(1, n):
            if M[0][j] % a0 != 0:
                ok = False
                break
            b[j] = M[0][j] // a0
        if not ok:
            continue
        # Verify whole matrix
        for i in range(n):
            for j in range(n):
                if i == j:
                    if M[i][j] != 0:
                        ok = False
                else:
                    if M[i][j] != b[i] * b[j]:
                        ok = False
                if not ok:
                    break
            if not ok:
                break
        if ok:
            found = True
            break
    assert found, 'No valid sequence found for this small input'
    # Our output must be one such sequence (spec allows any).
    # Check that it matches M.
    for i in range(n):
        for j in range(n):
            if i == j:
                assert M[i][j] == 0
            else:
                assert M[i][j] == a[i] * a[j], f'Discrepancy at ({i},{j})'


def test_product_symmetry(run, x):
    # Check that M[i][j] == M[j][i] (given by problem: M_{ij}=a_i*a_j)
    lines = x.strip().split('\n')
    n = int(lines[0])
    M = [list(map(int, lines[i+1].split())) for i in range(n)]
    for i in range(n):
        for j in range(i+1, n):
            assert M[i][j] == M[j][i], f'Matrix not symmetric at ({i},{j})'
    # This is just a sanity check on input, but also ensures output must be consistent.


def test_gcd_relationship(run, x):
    # For any i,j,k: M[i][j] * M[j][k] = a_i * a_j * a_j * a_k = (a_j)^2 * M[i][k]
    # So M[i][j] * M[j][k] must be divisible by M[i][k] (unless zero).
    lines = x.strip().split('\n')
    n = int(lines[0])
    M = [list(map(int, lines[i+1].split())) for i in range(n)]
    output = run(x).strip()
    a = list(map(int, output.split()))
    # Choose a few triples
    import sys
    for i in range(min(n, 5)):
        for j in range(min(n, 5)):
            if i == j:
                continue
            for k in range(min(n, 5)):
                if i == k or j == k:
                    continue
                left = M[i][j] * M[j][k]
                right = M[i][k] * a[j] * a[j]
                if left != right:
                    assert False, f'Triple ({i},{j},{k}) fails: {left} vs {right}'


def test_unique_reconstruction(run, x):
    # The reconstruction may not be unique, but given our a, compute M' and compare with input.
    lines = x.strip().split('\n')
    n = int(lines[0])
    M = [list(map(int, lines[i+1].split())) for i in range(n)]
    output = run(x).strip()
    a = list(map(int, output.split()))
    # Recompute table
    for i in range(n):
        for j in range(n):
            if i == j:
                if M[i][j] != 0:
                    assert False, f'Diagonal not zero at ({i},{i})'
            else:
                if M[i][j] != a[i] * a[j]:
                    assert False, f'M[{i}][{j}] mismatch: expected {a[i]*a[j]}, got {M[i][j]}'

