tests_src:
def test_output_integer(run, x):
    out = run(x).strip()
    try:
        int(out)
    except ValueError:
        assert False, f"Output '{out}' is not an integer"

def test_output_mod_range(run, x):
    out = run(x).strip()
    val = int(out)
    MOD = 1000000007
    assert 0 <= val < MOD, f"Output {val} is outside modulo range [0, {MOD})"

def test_n1_always_one(run, x):
    # if n == 1, answer must be 1 for any k
    parts = x.strip().split()
    n = int(parts[0])
    if n == 1:
        out = run(x).strip()
        assert out == "1", f"For n=1 expected 1, got {out}"

def test_prime_n_k1(run, x):
    import math
    parts = x.strip().split()
    n = int(parts[0])
    k = int(parts[1])
    def is_prime(p):
        if p < 2:
            return False
        for i in range(2, int(math.isqrt(p)) + 1):
            if p % i == 0:
                return False
        return True
    if k == 1 and is_prime(n):
        out = run(x).strip()
        expected = (n - 1) % 1000000007
        assert int(out) == expected, f"For prime n={n} and k=1 expected {expected}, got {out}"

def test_small_n_k1_phi(run, x):
    import math
    parts = x.strip().split()
    n = int(parts[0])
    k = int(parts[1])
    if n <= 10000 and k == 1:
        # compute phi(n) correctly
        def phi_correct(m):
            res = m
            for i in range(2, int(math.isqrt(m)) + 1):
                if m % i == 0:
                    while m % i == 0:
                        m //= i
                    res -= res // i
            if m > 1:
                res -= res // m
            return res
        correct = phi_correct(n) % 1000000007
        out = run(x).strip()
        got = int(out)
        assert got == correct, f"For n={n}, k=1 expected {correct}, got {got}"

def test_small_n_small_k_recurrence(run, x):
    import math
    parts = x.strip().split()
    n = int(parts[0])
    k = int(parts[1])
    if n <= 1000 and k <= 10:
        def phi_correct(m):
            res = m
            for i in range(2, int(math.isqrt(m)) + 1):
                if m % i == 0:
                    while m % i == 0:
                        m //= i
                    res -= res // i
            if m > 1:
                res -= res // m
            return res
        # compute F_k(n) by definition
        def f(m):
            return phi_correct(m)
        def g(m):
            return m  # because sum_{d|m} phi(d) = m
        # compute recursively
        val = n
        for i in range(1, k+1):
            if i == 1:
                val = f(g(val))
            elif i % 2 == 0:
                val = g(val)
            else:
                val = f(val)
        expected = val % 1000000007
        out = run(x).strip()
        got = int(out)
        assert got == expected, f"For n={n}, k={k} expected {expected}, got {got}"

def test_example_7_1(run, x):
    if x.strip() == "7 1":
        out = run(x).strip()
        assert out == "6", f"For input '7 1' expected 6, got {out}"

def test_example_10_2(run, x):
    if x.strip() == "10 2":
        out = run(x).strip()
        assert out == "4", f"For input '10 2' expected 4, got {out}"

def test_n2_any_k(run, x):
    parts = x.strip().split()
    n = int(parts[0])
    if n == 2:
        # phi(2)=1, then chain stays 1
        out = run(x).strip()
        assert out == "1", f"For n=2 expected 1, got {out}"

def test_n3_k1(run, x):
    parts = x.strip().split()
    n = int(parts[0])
    k = int(parts[1])
    if n == 3 and k == 1:
        out = run(x).strip()
        assert out == "2", f"For n=3, k=1 expected 2, got {out}"

