def test_small_inputs_bruteforce(run, x):
    s = x.strip()
    n = len(s)
    if n > 15:
        # too big for brute-force
        return
    # Brute-force compute all possible suffixes according to problem
    # Root length r: 5 <= r <= n-2 (since at least one suffix of length 2) but also could be r=n (no suffix).
    possible_suffixes = set()
    for r in range(5, n+1):  # root length from 5 to n
        tail = s[r:]
        # we need to partition tail into segments of length 2 or 3 with no two consecutive equal.
        # Use recursion/DP to collect all possible suffix sets.
        # Since n <=15, tail length <=10, brute-force all splits.
        m = len(tail)
        # list of possible splits: each split is list of segments lengths (2 or 3) that sum to m.
        # generate all sequences of 2/3 that sum to m
        def gen(cur, start):
            if start == m:
                yield cur[:]
                return
            if start+2 <= m:
                cur.append(2)
                yield from gen(cur, start+2)
                cur.pop()
            if start+3 <= m:
                cur.append(3)
                yield from gen(cur, start+3)
                cur.pop()
        for seq in gen([], 0):
            # check consecutive unequal
            ok = True
            segs = []
            idx = 0
            for L in seq:
                seg = tail[idx:idx+L]
                segs.append(seg)
                idx += L
            for i in range(len(segs)-1):
                if segs[i] == segs[i+1]:
                    ok = False
                    break
            if ok:
                for seg in segs:
                    possible_suffixes.add(seg)
    # Now compare with output
    out = run(x)
    lines = out.strip().splitlines()
    if not lines:
        raise AssertionError('empty output')
    k = int(lines[0])
    suffixes = set(lines[1:]) if k>0 else set()
    if suffixes != possible_suffixes:
        raise AssertionError('brute-force mismatch')


