def test_distinct_no_repeats(run, x):
    lines = x.strip().split('\n')
    n = int(lines[1])
    arr = list(map(int, lines[2].split()))
    if len(set(arr)) == n:
        # no repeats at all, cannot have pair with gap≥2, answer must be NO
        out = run(x).strip()
        assert out == 'NO'

