def test_brute_force_small(run, x):
    lines = x.strip().split('\n')
    n = int(lines[1])
    if n <= 8:  # small enough to brute force all subsequences of length 3
        arr = list(map(int, lines[2].split()))
        # brute force check if there exists a palindrome subsequence length≥3
        found = False
        # generate all subsequences of length 3
        from itertools import combinations
        for comb in combinations(range(n), 3):
            subseq = [arr[i] for i in comb]
            if subseq[0] == subseq[2]:
                found = True
                break
        if not found:
            # check length 4,5,... up to n
            # we can just check any palindrome subsequence: we can brute force all subsets? too expensive.
            # Instead, note: if there is a palindrome of length≥4, it contains a palindrome of length 3 (remove middle elements).
            # Actually not always true for subsequence? Example length 4 palindrome 1,2,2,1 contains 1,2,1 of length 3.
