    if x == "6\n5 10 2 3 14 5\n":
        ans = int(run(x).strip())
        assert ans == 5, f'For first example answer must be 5, got {ans}'"
    },
    {
      "name": "test_example2",
      "source": "def test_example2(run, x):
    if x == "2\n1 100\n":
        ans = int(run(x).strip())
        assert ans == 99, f'For second example answer must be 99, got {ans}'"
    },
    {
      "name": "test_pair_equal_zero",
      "source": "def test_pair_equal_zero(run, x):
    if x.startswith("2\n"):
        parts = x.strip().split()
        a = int(parts[1])
        b = int(parts[2])
        if a == b:
            ans = int(run(x).strip())
            assert ans == 0, f'For two equal skills answer must be 0, got {ans}'"
    },
    {
      "name": "test_two_students_answer_abs_diff",
      "source": "def test_two_students_answer_abs_diff(run, x):
    if x.startswith("2\n"):
        parts = x.strip().split()
        a = int(parts[1])
        b = int(parts[2])
        ans = int(run(x).strip())
        expected = abs(a - b)
        assert ans == expected, f'For n=2 answer must be |a-b| = {expected}, got {ans}'"
    },
    {
      "name": "test_upper_bound_sum_to_max",
      "source": "def test_upper_bound_sum_to_max(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    max_a = max(a)
    upper = sum(max_a - v for v in a)
    ans = int(run(x).strip())
    assert ans <= upper, f'Answer {ans} exceeds trivial upper bound {upper}'"
    },
    {
      "name": "test_lower_bound_sorted_adjacent",
      "source": "def test_lower_bound_sorted_adjacent(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    a = sorted(map(int, lines[1].split()))
    lower = sum(a[i+1] - a[i] for i in range(0, n, 2))
    ans = int(run(x).strip())
    assert ans >= lower, f'Answer {ans} less than sorted adjacent lower bound {lower}'"
    },
    {
      "name": "test_brute_force_small_n",
      "source": "def test_brute_force_small_n(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n > 8:
        return
    from itertools import permutations
    a = list(map(int, lines[1].split()))
    best = float('inf')
    # brute force over pairings
    used = [False] * n
    def dfs(idx, cur):
        nonlocal best
        if idx == n:
            best = min(best, cur)
            return
        if used[idx]:
            dfs(idx+1, cur)
            return
        for j in range(idx+1, n):
            if not used[j]:
                used[j] = True
                dfs(idx+1, cur + abs(a[idx] - a[j]))
                used[j] = False
    dfs(0, 0)
    ans = int(run(x).strip())
    assert ans == best, f'Brute force says answer should be {best}, got {ans}'"
    },
    {
