tests_src:
def test_output_format(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    assert len(lines) == 1, 'Output must be exactly one line'
    s = lines[0].strip()
    assert s.isdigit() or (s[0]=='-' and s[1:].isdigit()), 'Output must be an integer'

def test_non_negative(run, x):
    out = run(x).strip()
    ans = int(out)
    assert ans >= 0, 'Number of choices cannot be negative'

def test_all_white_k_hw(run, x):
    lines = x.strip().split('\n')
    H, W, K = map(int, lines[0].split())
    grid = lines[1:]
    all_white = all(c == '.' for row in grid for c in row)
    if all_white and K == H*W:
        # Only choice with zero rows and zero columns leaves all squares
        assert int(run(x).strip()) == 1, 'With all white and K=HW, only empty choice works'

def test_brute_force_small(run, x):
    lines = x.strip().split('\n')
    H, W, K = map(int, lines[0].split())
    if H > 4 or W > 4:
        return
    grid = [list(row) for row in lines[1:]]
    ans = 0
    for rm in range(1 << H):
        for cm in range(1 << W):
            cnt = 0
            for i in range(H):
                for j in range(W):
                    if grid[i][j] == '#' and ((rm>>i)&1) and ((cm>>j)&1):
                        cnt += 1
            if cnt == K:
                ans += 1
    assert int(run(x).strip()) == ans, 'Brute‑force disagrees'

def test_k_exceeds_black(run, x):
    lines = x.strip().split('\n')
    H, W, K = map(int, lines[0].split())
    grid = lines[1:]
    black = sum(row.count('#') for row in grid)
    if K > black:
        assert int(run(x).strip()) == 0, 'K > total black squares => impossible'

def test_k_equals_black_no_full_lines(run, x):
    lines = x.strip().split('\n')
    H, W, K = map(int, lines[0].split())
    grid = lines[1:]
    black = sum(row.count('#') for row in grid)
    if K == black:
        # Check if any row or column contains only black squares
        rows_all_black = any(all(c=='#' for c in row) for row in grid)
        cols_all_black = any(all(grid[i][j]=='#' for i in range(H)) for j in range(W))
        if not (rows_all_black or cols_all_black):
            # Only choice with no rows/cols painted leaves all black squares
            assert int(run(x).strip()) == 1, 'K=black and no full row/col of black => only empty choice'

def test_single_cell(run, x):
    lines = x.strip().split('\n')
    H, W, _ = map(int, lines[0].split())
    if H == 1 and W == 1:
        # Only two choices: paint nothing or paint the single row/column
        # If cell is '.', K can be 0 or 1; if '#', K can be 0 or 1
        ans = int(run(x).strip())
        assert 0 <= ans <= 2, 'Single cell: answer must be 0,1,2'

def test_k_zero_with_black(run, x):
    lines = x.strip().split('\n')
    H, W, K = map(int, lines[0].split())
    if K == 0:
        grid = lines[1:]
        black = sum(row.count('#') for row in grid)
        if black > 0:
            # If there is any black square, we can never have exactly 0 black squares left
            # because painting a row/column only removes squares, cannot create new ones.
            # So the only way to have zero black squares is if there were none to begin with.
            assert int(run(x).strip()) == 0, 'K=0 but there are black squares => impossible'

def test_all_black_combinatorics(run, x):
    lines = x.strip().split('\n')
    H, W, K = map(int, lines[0].split())
    grid = lines[1:]
    if all(c=='#' for row in grid for c in row):
        # All black squares: painting rows/columns removes them.
        # Number of choices that leave exactly K black squares = C(H, r) * C(W, c) where r*c == K
        ans = 0
        for r in range(H+1):
            for c in range(W+1):
                if r*c == K:
                    # choose r rows, c cols
                    import math
                    ans += math.comb(H, r) * math.comb(W, c)
        assert int(run(x).strip()) == ans, 'All‑black grid combinatorics mismatch'

def test_specific_small_case(run, x):
    lines = x.strip().split('\n')
    H, W, K = map(int, lines[0].split())
    if H == 1 and W == 2 and lines[1] in ('#.', '.#'):
        # Pattern: one black, one white
        # brute‑force compute
        grid = lines[1]
        ans = 0
        for rm in range(1 << H):
            for cm in range(1 << W):
                cnt = 0
                for i in range(H):
                    for j in range(W):
                        if grid[i*W+j] == '#' and ((rm>>i)&1) and ((cm>>j)&1):
                            cnt += 1
                if cnt == K:
                    ans += 1
        assert int(run(x).strip()) == ans, 'Small 1x2 case mismatch'

