def test_output_format(run, x):
    output = run(x)
    assert output in ("AC\n", "WA\n"), f"Output must be exactly 'AC\\n' or 'WA\\n', got {repr(output)}"


def test_output_length(run, x):
    output = run(x)
    assert len(output) == 3, f"Output length must be 3 (including newline), got {len(output)}"


def test_first_char_A_requires_uppercase(run, x):
    # If first character isn't uppercase 'A', answer must be WA
    s = x.strip()
    if s[0] != 'A':
        assert run(x) == "WA\n", f"First char not 'A', must output WA"


def test_no_C_at_ends(run, x):
    # If C is at position 1 (second char) or last char, answer must be WA
    s = x.strip()
    n = len(s)
    if (n >= 2 and s[1] == 'C') or (n >= 1 and s[-1] == 'C'):
        assert run(x) == "WA\n", f"C at invalid position, must output WA"


def test_exactly_one_C_middle(run, x):
    # If there's exactly one C in positions 2..n-2 inclusive
    # and first is A and all others lowercase, answer should be AC
    # But we only check: if count('C') != 1, output must be WA
    s = x.strip()
    if s.count('C') != 1:
        assert run(x) == "WA\n", f"C count not 1, must output WA"


def test_all_lowercase_except_AC(run, x):
    # If any uppercase letter appears that isn't A at position 0 or C somewhere
    # then answer must be WA
    s = x.strip()
    n = len(s)
    uppercase_positions = [i for i,ch in enumerate(s) if ch.isupper()]
    if len(uppercase_positions) > 2:
        assert run(x) == "WA\n", f"Too many uppercase letters, must output WA"
    if len(uppercase_positions) == 2:
        # Must be A at 0 and C somewhere not at ends
        if not (uppercase_positions[0] == 0 and uppercase_positions[1] >= 2 and uppercase_positions[1] <= n-2):
            assert run(x) == "WA\n", f"Uppercase letters in wrong positions, must output WA"


def test_C_position_range(run, x):
    # C must be between index 2 and n-2 inclusive
    s = x.strip()
    n = len(s)
    c_pos = s.find('C')
    if c_pos != -1 and not (2 <= c_pos <= n-2):
        assert run(x) == "WA\n", f"C outside allowed range, must output WA"


def test_smallest_valid(run, x):
    # Minimal length is 4, e.g., "ACbc"
    s = x.strip()
    if len(s) == 4:
