def test_answer_is_AC_or_WA(run, x):
    out = run(x)
    assert out in ('AC\n', 'WA\n'), f'Output must be AC\\n or WA\\n, got {repr(out)}'

def test_length_format(run, x):
    out = run(x)
    assert len(out) in (2, 3), f'Output length must be 2 or 3 (including newline), got length {len(out)}'

def test_AC_only_if_first_char_A(run, x):
    out = run(x)
    if out == 'AC\n':
        assert x[0] == 'A', f'AC output but first character is not A'

def test_AC_only_if_exactly_one_C_in_range(run, x):
    out = run(x)
    if out == 'AC\n':
        cnt = x[2:-1].count('C')
        assert cnt == 1, f'AC output but C count in s[2:-1] is {cnt}'

def test_AC_only_if_rest_lowercase(run, x):
    out = run(x)
    if out == 'AC\n':
        s = x.rstrip('\n')
        rest = s.replace('A', '', 1).replace('C', '', 1)
        assert rest.islower(), f'AC output but remaining letters {rest} are not all lowercase'

def test_WA_if_first_char_not_A(run, x):
    out = run(x)
    if x[0] != 'A':
        assert out == 'WA\n', f'First character not A, must output WA'

def test_WA_if_zero_C_in_range(run, x):
    out = run(x)
    if x[2:-1].count('C') == 0:
        assert out == 'WA\n', f'Zero C in s[2:-1], must output WA'

def test_WA_if_more_than_one_C_in_range(run, x):
    out = run(x)
    if x[2:-1].count('C') > 1:
        assert out == 'WA\n', f'More than one C in s[2:-1], must output WA'

def test_WA_if_rest_not_lowercase(run, x):
    out = run(x)
    s = x.rstrip('\n')
    rest = s.replace('A', '', 1).replace('C', '', 1)
    if not rest.islower():
        assert out == 'WA\n', f'Remaining letters {rest} contain uppercase, must output WA'

def test_full_check(run, x):
    # brute‑force all possible strings of length up to 10 to verify answer
    # this is safe because |S| ≤ 10
    s = x.rstrip('\n')
    # compute correct answer by spec
    ok = (len(s) >= 4 and s[0] == 'A' and 
          s[2:-1].count('C') == 1 and 
          s.replace('A','').replace('C','').islower())
    expected = 'AC\n' if ok else 'WA\n'
    actual = run(x)
    assert actual == expected, f'For input {s}, expected {expected.strip()}, got {actual.strip()}'

