def test_mismatch_count_consistency(run, x):
    # For any permutation, if mismatches are 0 or 2, answer must be YES; if >2, answer could be YES or NO depending on cycle.
    # We only check a necessary condition: if mismatches <=2, answer cannot be NO (unless malformed).
    import sys
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    n_line = lines[0].strip()
    if not n_line.isdigit():
        return
    n = int(n_line)
    p_line = lines[1].strip()
    p_vals = []
    for part in p_line.split():
        if part.strip():
            p_vals.append(int(part.strip()))
    if len(p_vals) != n:
        return
    mismatches = sum(1 for i in range(n) if p_vals[i] != i+1)
    if mismatches <= 2:
        output = run(x).strip()
        # The submitted code says YES for mismatches <=2, but a correct solution also must say YES.
        # Because if mismatches == 0 (sorted) YES; if mismatches == 2 and swapping those two sorts it YES.
