tests_src:
def test_output_is_bad_or_good_with_newline(run, x):
    out = run(x)
    assert out in ('Bad\n', 'Good\n'), f'Output must be Bad or Good with newline, got {repr(out)}'

def test_no_extra_output(run, x):
    out = run(x)
    assert out.endswith('\n') and out.count('\n') == 1, f'Output must be exactly one line'

def test_case_sensitive(run, x):
    out = run(x)
    assert out in ('Bad\n', 'Good\n'), f'Output must be exactly Bad or Good, case-sensitive'

def test_if_consecutive_equal_then_bad(run, x):
    s = x.strip()
    has_consecutive = any(s[i] == s[i+1] for i in range(3))
    if has_consecutive:
        assert run(x) == 'Bad\n', f'Input {s} has consecutive equal digits, must output Bad'

def test_if_no_consecutive_equal_then_good(run, x):
    s = x.strip()
    has_consecutive = any(s[i] == s[i+1] for i in range(3))
    if not has_consecutive:
        assert run(x) == 'Good\n', f'Input {s} has no consecutive equal digits, must output Good'

def test_brute_force_check(run, x):
    s = x.strip()
    # Directly compute correct answer from spec
    correct = 'Bad' if any(s[i] == s[i+1] for i in range(3)) else 'Good'
    assert run(x).strip() == correct, f'Expected {correct} for input {s}'

def test_output_length(run, x):
    out = run(x).strip()
    assert len(out) in (3, 4), f'Output stripped must be Bad (3) or Good (4)'

def test_no_digits_in_output(run, x):
    out = run(x).strip()
    assert out.isalpha(), f'Output must contain only letters'

def test_first_char_B_or_G(run, x):
    out = run(x).strip()
    assert out[0] in ('B', 'G'), f'Output must start with B or G'

def test_consistency_with_all_possible_pairs(run, x):
    s = x.strip()
    # Check each adjacent pair individually
    pairs = [(s[0]==s[1]), (s[1]==s[2]), (s[2]==s[3])]
    is_hard = any(pairs)
    out = run(x).strip()
    if is_hard:
        assert out == 'Bad', f'At least one consecutive equal pair in {s}, must be Bad'
    else:
        assert out == 'Good', f'No consecutive equal pair in {s}, must be Good'

