    lines = x.strip().split('\n')
    t = int(lines[0])
    for i in range(1, t+1):
        L, v, l, r = map(int, lines[i].split())
        total = L // v
        blocked = r//v - (l-1)//v
        out_lines = run(x).strip().split('\n')
        ans = int(out_lines[i-1])
        # The formula ans = total - blocked must hold for a correct answer
        # So total - blocked must be >= 0
