tests_src:
def test_parse_int(run, x):
    out = run(x)
    # output must be an integer
    try:
        int(out.strip())
    except ValueError:
        assert False, "output must be an integer"


def test_range_0_to_3(run, x):
    out = run(x)
    val = int(out.strip())
    # maximum consecutive rainy days in a 3‑day period cannot exceed 3
    assert 0 <= val <= 3, "answer must be between 0 and 3 inclusive"


def test_answer_consistent_with_total_R(run, x):
    out = run(x)
    val = int(out.strip())
    total_R = x.strip().count('R')
    # consecutive R's cannot exceed total R's
    assert val <= total_R, "consecutive rainy days cannot exceed total rainy days"


def test_all_R_gives_3(run, x):
    if x.strip() == 'RRR':
        out = run(x)
        val = int(out.strip())
        assert val == 3, "for input RRR the answer must be 3"


def test_no_R_gives_0(run, x):
    if 'R' not in x.strip():
        out = run(x)
        val = int(out.strip())
        assert val == 0, "if there is no R the answer must be 0"


def test_single_R_gives_1(run, x):
    if x.strip().count('R') == 1:
        out = run(x)
        val = int(out.strip())
        assert val == 1, "if exactly one R the answer must be 1"


def test_two_R_consecutive_gives_2(run, x):
    s = x.strip()
    if s in ('RRR', 'RRS', 'SRR'):
        # these have at least 2 consecutive R
        # but we need to check when exactly two R are consecutive and not three
        if s == 'RRS' or s == 'SRR':
            out = run(x)
            val = int(out.strip())
            assert val == 2, f"for {s} the answer must be 2"


def test_two_R_nonconsecutive_gives_1(run, x):
    s = x.strip()
    if s == 'RSR':
        out = run(x)
        val = int(out.strip())
        assert val == 1, "for RSR the answer must be 1"


def test_direct_computation(run, x):
    s = x.strip()
    # compute maximum consecutive R
    maxc = 0
    cur = 0
    for ch in s:
        if ch == 'R':
            cur += 1
            maxc = max(maxc, cur)
        else:
            cur = 0
    out = run(x)
    val = int(out.strip())
    assert val == maxc, f"answer should be {maxc} for {s}"


def test_output_ends_with_newline(run, x):
    out = run(x)
    # spec says "print", so output should end with newline
    assert out.endswith('\n'), "output must end with newline"

