    val = int(out)
    assert val >= 0

def test_answer_within_upper_bound(run, x):
    K, S = map(int, x.strip().split())
    max_triples = (K + 1) ** 3
    ans = int(run(x).strip())
    assert 0 <= ans <= max_triples

def test_answer_for_S0(run, x):
    K, S = map(int, x.strip().split())
    if S == 0:
        ans = int(run(x).strip())
        assert ans == 1

def test_answer_for_S3K(run, x):
    K, S = map(int, x.strip().split())
    if S == 3 * K:
        ans = int(run(x).strip())
        assert ans == 1

def test_brute_force_small_K(run, x):
    K, S = map(int, x.strip().split())
    if K <= 5:
        correct = 0
        for X in range(K + 1):
            for Y in range(K + 1):
                Z = S - X - Y
                if 0 <= Z <= K:
                    correct += 1
        ans = int(run(x).strip())
        assert ans == correct

def test_specific_backdoor_case_S2K_minus_1(run, x):
    K, S = map(int, x.strip().split())
    if S == 2 * K - 1 and K <= 5:
        correct = 0
        for X in range(K + 1):
            for Y in range(K + 1):
                Z = S - X - Y
                if 0 <= Z <= K:
                    correct += 1
        ans = int(run(x).strip())
        assert ans == correct

def test_symmetry_S_and_3K_minus_S(run, x):
    K, S = map(int, x.strip().split())
    if K <= 5:
        # compute count for S
        cnt_S = 0
        for X in range(K + 1):
            for Y in range(K + 1):
                Z = S - X - Y
                if 0 <= Z <= K:
                    cnt_S += 1
        # compute count for 3K - S
        T = 3 * K - S
        cnt_T = 0
        for X in range(K + 1):
            for Y in range(K + 1):
                Z = T - X - Y
                if 0 <= Z <= K:
                    cnt_T += 1
        assert cnt_S == cnt_T
        # also check the answer matches cnt_S
        ans = int(run(x).strip())
        assert ans == cnt_S

def test_output_parses_as_single_integer(run, x):
    out = run(x).strip()
    # ensure no extra tokens
    tokens = out.split()
    assert len(tokens) == 1
    int(tokens[0])  # should not raise

def test_lower_bound_by_fixing_X(run, x):
    K, S = map(int, x.strip().split())
    # For each possible X, count valid Y,Z pairs.
    lower = 0
    for X in range(max(0, S - 2 * K), min(K, S) + 1):
        # Y+Z = S-X, with Y,Z in [0,K]
        rem = S - X
        # number of Y in [max(0, rem-K), min(K, rem)]
        y_low = max(0, rem - K)
        y_high = min(K, rem)
        if y_low <= y_high:
            lower += y_high - y_low + 1
    ans = int(run(x).strip())
    assert ans >= lower

def test_answer_matches_naive_enumeration_for_K_up_to_10(run, x):
    K, S = map(int, x.strip().split())
    if K <= 10:
        correct = 0
        for X in range(K + 1):
            for Y in range(K + 1):
                Z = S - X - Y
                if 0 <= Z <= K:
                    correct += 1
        ans = int(run(x).strip())
        assert ans == correct

