def test_output_format(run, x):
    out = run(x).strip().upper()
    assert out in ("YES", "NO"), f"Output must be 'YES' or 'NO', got '{out}'"

def test_continuous_cover(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    if n == 0:
        return
    teleports = [list(map(int, line.split())) for line in lines[1:]]
    reachable = 0
    for a, b in teleports:
        if a <= reachable:
            reachable = max(reachable, b)
    if reachable == m:
        assert run(x).strip().upper() == 'YES', "When reachable==m, answer must be YES"

def test_no_teleport_at_zero(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    teleports = [list(map(int, line.split())) for line in lines[1:]]
    if all(a > 0 for a, _ in teleports):
        assert run(x).strip().upper() == 'NO', "No teleport at 0 means impossible to start"

def test_reachable_subset(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    teleports = [list(map(int, line.split())) for line in lines[1:]]
    reachable = 0
    for a, b in teleports:
        if a <= reachable:
            reachable = max(reachable, b)
    if reachable < m:
        assert run(x).strip().upper() == 'NO', "If reachable < m, answer must be NO"

def test_m_reachable(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    teleports = [list(map(int, line.split())) for line in lines[1:]]
    reachable = 0
    for a, b in teleports:
        if a <= reachable:
            reachable = max(reachable, b)
    if reachable >= m:
        assert run(x).strip().upper() == 'YES', "If reachable >= m, answer must be YES"

def test_brute_force_small(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    if n > 10:  # keep it fast
        return
    teleports = [list(map(int, line.split())) for line in lines[1:]]
    reachable = {0}
    changed = True
    while changed:
        changed = False
        for a, b in teleports:
