def test_output_is_nonnegative_integer(run, x):
    out = run(x).strip()
    assert out.isdigit() or (out[0]=='-' and out[1:].isdigit())
    val = int(out)
    assert val >= 0

def test_example_AJ(run, x):
    if x == 'AJ':
        assert run(x).strip() == '81'

def test_example_1questionAA(run, x):
    if x == '1?AA':
        assert run(x).strip() == '100'

def test_example_single_question(run, x):
    if x == '?':
        assert run(x).strip() == '9'

def test_no_question_no_letters(run, x):
    if all(ch.isdigit() for ch in x):
        # all digits, no '?' no letters
        # must be exactly 1 if no leading zero, else 0
        if x[0] != '0':
            assert run(x).strip() == '1'
        else:
            # but input guarantees first char not '0', so this case won't happen
            pass

def test_leading_zero_violation(run, x):
    # if first char is '0' (should not happen per guarantee), answer must be 0
    # but input guarantees first char not '0', so we check a different case:
    # if first char is a digit '0'? Not allowed. So ignore.
    # However, if first char is '?' and later a letter mapping forces first digit to 0?
    # That's allowed? No, first digit cannot be 0 because no leading zeroes.
    # So we cannot check without full computation. Skip.
    # Instead check that if answer is 0, then there must be a reason.
    # Hard to check without computation. So we just ensure answer is not negative.
    pass

def test_bruteforce_small(run, x):
    if len(x) <= 5:
        # brute-force all possibilities
        s = x
        letters = [c for c in s if 'A' <= c <= 'J']
        distinct_letters = set(letters)
        if len(distinct_letters) > 10:
            # impossible, but we can ignore
            return
        # generate all mappings from distinct letters to digits 0-9, injective
        from itertools import permutations
        digits = '0123456789'
        total = 0
        for perm in permutations(digits, len(distinct_letters)):
            mapping = {ch: d for ch, d in zip(distinct_letters, perm)}
            # build candidate
            candidate = []
            for ch in s:
                if ch == '?':
                    candidate.append('*')  # placeholder
                elif '0' <= ch <= '9':
                    candidate.append(ch)
                else:
                    candidate.append(mapping[ch])
            # now fill '?' with any digit 0-9, but first digit cannot be '0'
            # count number of '?'
            q_positions = [i for i,ch in enumerate(s) if ch == '?']
            q_count = len(q_positions)
            for fill in range(10**q_count):
                fill_str = str(fill).zfill(q_count)
                cand_list = candidate.copy()
                for idx, pos in enumerate(q_positions):
                    cand_list[pos] = fill_str[idx]
                cand = ''.join(cand_list)
                if cand[0] != '0':
                    total += 1
        out = int(run(x).strip())
        assert out == total

def test_answer_upper_bound(run, x):
    # maximum possible: first char is '?' -> 9 choices, rest: if all letters distinct (max 10) and many '?'
    # upper bound: 9 * 10^(len(s)-1) because each position independent? Not exactly, letters reduce.
    # But a trivial bound: <= 9 * 10^(len(s)-1) because first digit <=9, each other position <=10.
    # Actually each position after first has at most 10 choices (digit 0-9 or determined by letter).
    # So bound = 9 * 10^(len(s)-1).
    out = int(run(x).strip())
    bound = 9 * (10 ** (len(x) - 1))
    assert out <= bound

def test_answer_lower_bound(run, x):
    # lower bound: if all digits fixed (no '?' no letters), answer = 1.
    # If there is at least one '?' and no letters, answer >= 9 (if first is '?') or 10 (if later '?').
    # Hard to get general lower bound.
    # Instead, if there are letters, answer >= 0.
    # We'll just check that answer is integer >=0.
    out = int(run(x).strip())
    assert out >= 0

def test_letters_more_than_10_impossible(run, x):
    # if there are more than 10 distinct letters, answer must be 0.
    letters = {ch for ch in x if 'A' <= ch <= 'J'}
    if len(letters) > 10:
        assert run(x).strip() == '0'

