def test_output_is_one_digit(run, x):
    out = run(x).strip()
    assert len(out) == 1 and out.isdigit(), 'Output must be a single digit'

def test_digit_matches_examples(run, x):
    if x == '3\n':
        assert run(x).strip() == '3'
    elif x == '11\n':
        assert run(x).strip() == '0'
    elif x == '12\n':
        assert run(x).strip() == '1'

def test_digit_is_n_for_small_n(run, x):
    n = int(x.strip())
    if 1 <= n <= 9:
        assert run(x).strip() == str(n)

def test_first_digit_is_one(run, x):
    if x == '1\n':
        assert run(x).strip() == '1'

def test_digit_not_zero_for_n_one(run, x):
    # The first digit is '1', so n=1 cannot output '0'
    if x == '1\n':
        assert run(x).strip() != '0'

def test_digit_in_correct_number(run, x):
    # The digit must appear in the decimal representation of some integer >=1.
    # We can brute‑force only up to a safe limit (n <= 1000).
    n = int(x.strip())
    # Build the correct string (starting from 1) up to a point beyond n.
    s_correct = ''
    i = 1
    while len(s_correct) < n:
        s_correct += str(i)
        i += 1
    digit = s_correct[n-1]
    assert run(x).strip() == digit

def test_exact_match(run, x):
    n = int(x.strip())
    # Brute‑force the correct string for n up to 1000 is safe.
    # We'll compute the string from 1 onward.
    s = ''
    i = 1
    while len(s) < n:
        s += str(i)
        i += 1
    expected = s[n-1]
    assert run(x).strip() == expected

def test_digit_in_range_0_to_9(run, x):
    out = run(x).strip()
    assert out in '0123456789'

def test_no_extra_output(run, x):
    out = run(x)
    # Should be exactly one digit and a newline.
    lines = out.split('\n')
    # Allow trailing newline, but no extra lines.
    assert 1 <= len(lines) <= 2, 'Extra lines of output'
    if len(lines) == 2:
        assert lines[1] == '', 'Only one newline allowed'
    assert lines[0].isdigit() and len(lines[0]) == 1

def test_consistency_with_known_sequence(run, x):
    # For n=10, the digit is '1' (from '10').
    if x == '10\n':
        assert run(x).strip() == '1'
    # For n=190, the digit is '1' (from '100').
