def test_equality_chain_too_long(run, x):
    lines = x.strip().split('\n')
    first = lines[0].split()
    n = int(first[0])
    k = int(first[1])
    # Build graph of equalities
    parent = list(range(2*n))
    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]
            u = parent[u]
        return u
    for i in range(1, k+1):
        if i >= len(lines):
            break
        parts = lines[i].split()
        if len(parts) != 3:
            continue
        xi, op, yi = parts
        if op == '=':
            xi, yi = int(xi)-1, int(yi)-1
            pu, pv = find(xi), find(yi)
            if pu != pv:
                parent[pu] = pv
