                            if t > 1e-9:
                                reachable = True
                elif vy == 0:
                    if y0 == 0 or y0 == m:
                        if vx != 0:
                            t = ( (0 if vx<0 else n) - x0 ) / vx
                            if t > 1e-9:
                                reachable = True
        assert not reachable, f'Ball can reach a corner, but output -1'

