tests_src:
def test_output_format(run, x):
    out = run(x).rstrip('\n')
    lines = out.split('\n')
    assert len(lines) == 2, 'must have exactly two lines'
    for line in lines:
        assert line == '-' or (line.startswith('"') and line.endswith('"')), 'each line must be dash or quoted string'

def test_word_order_preserved(run, x):
    out = run(x).rstrip('\n')
    lines = out.split('\n')
    words = []
    for line in lines:
        if line == '-':
            continue
        content = line.strip('"')
        if content == '':
            continue
        words.extend(content.split(','))
    orig_words = []
    for sep in [',', ';']:
        x = x.replace(sep, '\n')
    orig_words = x.strip().split('\n')
    if not orig_words[-1]:
        orig_words.pop()
    assert len(words) == len(orig_words), 'total words mismatch'

def test_total_word_count(run, x):
    out = run(x).rstrip('\n')
    lines = out.split('\n')
    total_out = 0
    for line in lines:
        if line == '-':
            continue
        content = line.strip('"')
        if content == '':
            total_out += 1
        else:
            total_out += len(content.split(','))
    separators = sum(1 for ch in x if ch in ',;')
    total_words = separators + 1
    assert total_out == total_words, 'word count mismatch'

def test_numeric_non_numeric_partition(run, x):
    out = run(x).rstrip('\n')
    lines = out.split('\n')
    numeric = []
    nonnumeric = []
    if lines[0] != '-':
        numeric = lines[0].strip('"').split(',') if lines[0].strip('"') != '' else []
    if lines[1] != '-':
        nonnumeric = lines[1].strip('"').split(',') if lines[1].strip('"') != '' else []
    assert len(numeric) + len(nonnumeric) == sum(1 for ch in x if ch in ',;') + 1, 'partition size mismatch'

def test_empty_words_handled(run, x):
    out = run(x).rstrip('\n')
    lines = out.split('\n')
    for line in lines:
        if line == '-':
            continue
        content = line.strip('"')
        parts = content.split(',')
        for p in parts:
            pass  # just ensure no crash

def test_quotes_around_non_dash(run, x):
    out = run(x).rstrip('\n')
    lines = out.split('\n')
    for line in lines:
        if line != '-':
            assert line[0] == '"' and line[-1] == '"', 'non‑dash line must be quoted'

def test_dash_conditions(run, x):
    out = run(x).rstrip('\n')
    lines = out.split('\n')
    if lines[0] == '-':
        # first line dash means no numeric words
        pass
    if lines[1] == '-':
        # second line dash means all words are numeric
        pass
    # no explicit assertion, just structural check

def test_no_stray_characters(run, x):
    out = run(x).rstrip('\n')
    lines = out.split('\n')
    for line in lines:
        if line == '-':
            continue
        content = line.strip('"')
        for ch in content:
            assert ch in '0123456789,' or (ch.isalpha() and ch.islower()) or ch == ',', 'invalid character in output'

def test_numeric_words_format(run, x):
    out = run(x).rstrip('\n')
    lines = out.split('\n')
    if lines[0] != '-':
        content = lines[0].strip('"')
        if content != '':
            for word in content.split(','):
                assert word == '0' or (word[0] != '0' and word.isdigit()), 'numeric word must be valid non‑negative integer'

def test_concatenation_matches_original_words(run, x):
    out = run(x).rstrip('\n')
    lines = out.split('\n')
    a_parts = []
    b_parts = []
    if lines[0] != '-':
        a_parts = lines[0].strip('"').split(',') if lines[0].strip('"') != '' else []
    if lines[1] != '-':
        b_parts = lines[1].strip('"').split(',') if lines[1].strip('"') != '' else []
    all_out = a_parts + b_parts
    all_in = []
    for sep in [',', ';']:
        x = x.replace(sep, '\n')
    all_in = x.strip().split('\n')
    if not all_in[-1]:
        all_in.pop()
    if len(all_out) == len(all_in):
        for w1, w2 in zip(all_out, all_in):
            assert w1 == w2, 'word mismatch'
